comms.text:
@1 וּשְׁלַח יַעֲקֹב אִזְגַּדִּין קֳדָמוֹהִי לְוַת עֵשָׂו אֲחוּהִי לְאַרְעָא דְשֵׂעִיר לַחֲקַל דְאֱדוֹם:
@2 וּפַקִּיד יָתְהוֹן לְמֵימָר כְּדֵין תֵּימְרוּן לְרִבּוֹנִי לְעֵשָׂו כִּדְנַן אֲמַר עַבְדָּךְ יַעֲקֹב עִם לָבָן דָּרִית וְאוֹחָרִית עַד כְּעָן:
@3 וַהֲוָה לִי תּוֹרִין וַחֲמָרִין עָאן וְעַבְדִּין וְאַמְהָן וּשְׁלָחִית לְחַוָּאָה לְרִבּוֹנִי לְאַשְׁכָּחָא רַחֲמִין בְּעֵינָךְ:
@4 וְתָבוּ אִזְגַּדַּיָּא לְוַת יַעֲקֹב לְמֵימָר אֲתֵינָא לְוַת אָחוּךְ לְוַת עֵשָׂו וְאַף אָתֵי לְקַדָּמוּתָךְ וְאַרְבַּע מְאָה גַּבְרָא עִמֵּהּ:
@5 וּדְחִיל יַעֲקֹב לַחֲדָא וַעֲקַת לֵהּ וּפַלִּיג יָת עַמָּא דִּי עִמֵּהּ וְיָת עָנָא וְיָת תּוֹרֵי וְגַמְלַיָּא לִ:תרֵין מַשִּׁירְיָן:
@6 וַאֲמַר אִם יֵיתֵי עֵשָׂו לְמַשְׁרִיתָא חֲדָא וְיִמְחִנֵּהּ וִיהֵי (נ''י וְיִמְחֵנַּהּ וּתְהִי) מַשְׁרִיתָא דְאִשְׁתָּאַר לְשֵׁיזָבָא:
@7 וַאֲמַר יַעֲקֹב אֱלָהֵהּ דְּאַבָּא אַבְרָהָם וֵאֱלָהֵהּ דְּאַבָּא יִצְחָק יְיָ דִּי אֲמַר לִי תּוּב לְאַרְעָךְ וּלְיַלָּדוּתָךְ וְאוֹטֵיב עִמָּךְ:
@8 זְעִירָן זָכוּתַי מִכֹּל חִסְדִּן וּמִכָּל טַבְוָן דִּי עֲבַדְתָּ עִם עַבְדָּךְ אֲרֵי יְחִידִי עֲבָרִית יָת יַרְדְּנָא הָדֵין וּכְעַן הֲוֵיתִי לִתְרֵין (נ''י לְתַרְתֵּין) מַשִּׁרְיָן:
@9 שֵׁזַבְנִי כְעַן מִידָא דְאָחִי מִידָא דְעֵשָׁו אֲרֵי דַחֵל אֲנָא מִנֵּהּ דִּילְמָא יֵיתֵי וְיִמְחִנַּנִי אִמָּא עַל בְּנַיָּא:
@10 וְאַתְּ אֲמַרְתָּ אוֹטָבָא אוֹטִיב עִמָּךְ וֶאֱשַׁוֵּי יָת בְּנָיךְ סַגִּיאִין כְּחַלָּא דְיַמָּא דִּי לָא יִתִּמְנוּן מִסַּגִּי:
@11 וּבָת תַּמָּן בְּלֵילְיָא הַהוּא וּנְסִיב מִן דְּאַיְתִי בִּידֵהּ תִּקְרֻבְתָּא לְעֵשָׂו אֲחוּהִי:
@12 עִזֵּי מָאתָן וּתְיָשַׁיָא עֶסְרִין רְחֵלִין מָאתָן וְדִכְרִין עֶסְרִין:
@13 גַּמְלֵי מֶנְקָתָא וּבְנֵיהוֹן תְּלָתִין תּוֹרְתָא אַרְבְּעִין וְתוֹרֵי עַסְרָא אַתְנָן עֶסְרִין וְעִירֵי עַסְרָא:
@14 וִיהַב בְּיַד עַבְדּוֹהִי עֶדְרָא עֶדְרָא בִּלְחוֹדוֹהִי וַאֲמַר לְעַבְדּוֹהִי עִבָּרוּ קֳדָמַי וּרְוָחָא תְּשַׁווּן בֵּין עֶדְרָא וּבֵין עֶדְרָא:
@15 וּפַקִד יָת קַדְמָאָה לְמֵימָר אֲרֵי יְעַרְעִנָּךְ עֵשָׂו אָחִי וּשְׁאֵלִנָּךְ לְמֵימָר לְמָן אַתְּ וּלְאָן אַתְּ אָזֵל וּלְמָן אִלֵּין דִּקֳדָמָךְ:
@16 וְתֵימַר לְעַבְדָךְ לְיַעֲקֹב תִּקְרֻבְתָּא הִיא דִמְשַׁלְּחָא לְרִבּוֹנִי לְעֵשָׂו וְהָא אַף הוּא אָתֵי בַתְרָנָא:
@17 וּפַקִּיד אַף יָת תִּנְיָנָא אַף יָת תְּלִיתָאָה אַף יָת כָּל דְּאָזְלִין בָּתַר עֲדָרַיָּא לְמֵימָר כְּפִתְגָּמָא הָדֵין תְּמַלְּלוּן עִם עֵשָׂו כַּד תַּשְׁכְּחוּן יָתֵהּ:
@18 וְתֵימְרוּן אַף הָא עַבְדָּךְ יַעֲקֹב אָתֵי בַתְרָנָא אֲרֵי אֲמַר אַנְחִנֵּהּ לְרוּגְזֵהּ בְּתִקְרֻבְתָּא דְּאָזְלַת קֳדָמַי וּבָתַר כֵּן אֶחֱזֵי אַפּוֹהִי מָאִים יִסַּב אַפָּי:
@19 וַעֲבָרַת תִּקְרֻבְתָּא עַל אַפּוֹהִי וְהוּא בָת בְּלֵילְיָא הַהוּא בְּמַשְׁרִיתָא:
@20 וְקָם בְּלֵילְיָא הוּא וּדְבַר יָת תַּרְתֵּין נְשׁוֹהִי וְיָת תַּרְתֵּין לְחֵינָתֵהּ וְיָת חַד עֲסַר בְּנוֹהִי וַעֲבַר יָת מַעֲבַר יוּבְקָא:
@21 וּדְבָרִנּוּן וְעַבָּרִנּוּן יָת נַחְלָא וְאַעְבַּר יָת דִּילֵהּ:
@22 וְאִשְׁתָּאַר יַעֲקֹב בִּלְחוֹדוֹהִי וְאִשְׁתַּדֵּל גַּבְרָא עִמֵּהּ עַד דִּסְלֵק צַפְרָא:
@23 וַחֲזָא אֲרֵי לָא יָכִיל לֵהּ וּקְרֵב בִּפְתֵי יַרְכֵּהּ וְזָע פְּתֵי יַרְכָּא דְיַעֲקֹב בְּאִשְׁתַּדָּלוּתֵהּ עִמֵּהּ:
@24 וַאֲמַר שַׁלְּחַנִּי אֲרֵי סְלִיק צַפְרָא וַאֲמַר לָא אֲשַׁלְחִנָךְ אֶלָּהֵין בֵּרַכְתָּנִי:
@25 וַאֲמַר לֵהּ מָה שְׁמָךְ וַאֲמַר יַעֲקֹב:
@26 וַאֲמַר לָא יַעֲקֹב יִתְאֲמַר עוֹד שְׁמָךְ אֶלָּהֵין יִשְׂרָאֵל אֲרֵי רַבְרְבַת קֳדָם יְיָ וְעִם גּוּבְרַיָּא וִיכָלְתָּא:
@27 וּשְׁאֵל יַעֲקֹב וַאֲמַר חַוִּי כְעַן שְׁמָךְ וַאֲמַר לְמָה דְנַן אַתְּ שָׁאֵל לִשְׁמִי וּבָרִיךְ יָתֵהּ תַּמָּן:
@28 וּקְרָא יַעֲקֹב שְׁמָא דְאַתְרָא פְּנִיאֵל אֲרֵי חֲזֵיתִי מַלְאָכַיָּא דַּיְיָ אַפִּין בְּאַפִּין וְאִשְׁתְּזָבַת נַפְשִׁי:
@29 וּדְנַח לֵהּ שִׁמְשָׁא כְּמָא דִּי עֲבַר יָת פְּנוּאֵל וְהוּא מַטְלַע עַל יַרְכֵּהּ:
@30 עַל כֵן לָא יֵיכְלוּן בְּנֵי יִשְׂרָאֵל יָת גִּידָא דְנַשְׁיָא דִּי עַל פְּתֵי יַרְכָּא עַד יוֹמָא הָדֵין אֲרֵי קְרֵיב בִּפְתֵי יַרְכָּא דְיַעֲקֹב בְּגִידָא דְנַשְׁיָא:
@31 וּזְקַף יַעֲקֹב עֵינוֹהִי וַחֲזָא וְהָא עֵשָׂו אֲתָא וְעִמֵּהּ אַרְבַּע מְאָה גֻּבְרִין וּפַלִּיג יָת בְּנַיָּא עַל לֵאָה וְעַל רָחֵל וְעַל תַּרְתֵּין לְחֵינָתָא:
@32 וְשַׁוִּי יָת לְחֵינָתָא וְיָת בְּנֵיהֶן קַדְמָאִין וְיָת לֵאָה וּבְנָהָא בַּתְרָאִין וְיָת רָחֵל וְיָת יוֹסֵף בַּתְרָאִין:
@33 וְהוּא עֲבַר קֳדָמֵיהוֹן וּסְגִיד עַל אַרְעָא שְׁבַע זִמְנִין עַד מִקְרְבֵהּ עַד (נ''י לְוַת) אֲחוּהִי:
@34 וּרְהַט עֵשָׂו לְקַדָּמוּתֵהּ וְגַפְּפֵהּ וּנְפַל עַל צַוְּארֵהּ וְנַשְׁקֵהּ וּבְכוֹ:
@35 וּזְקַף יָת עֵינוֹהִי וַחֲזָא יָת נְשַׁיָּא וְיָת בְּנַיָּא וַאֲמַר מָן אִלֵּין לָךְ וַאֲמַר בְּנַיָּא דִּי חַן יְיָ יָת עַבְדָּךְ:
@36 וּקְרִיבָן לְחֵינָתָא אִנוּן וּבְנֵיהֶן וּסְגִידוּ:
@37 וּקְרִיבָא אַף לֵאָה וּבְנָהָא וּסְגִידוּ וּבָתַר כֵּן קְרֵיב יוֹסֵף וְרָחֵל וּסְגִידוּ:
@38 וַאֲמַר מָן לָךְ כָּל מַשְׁרִיתָא הָדֵין דִּי עֲרָעִית וַאֲמַר לְאַשְׁכָּחָא רַחֲמִין בְּעֵינֵי רִבּוֹנִי:
@39 וַאֲמַר עֵשָׂו אִית לִי סַגִּי אָחִי אַצְלַח בְּדִילָךְ:
@40 וַאֲמַר יַעֲקֹב בְּבָעוּ אִם כְּעַן אַשְׁכָּחִית רַחֲמִין בְּעֵינָיךְ וּתְקַבֵּל תִּקְרֻבְתִּי מִן יְדִי אֲרֵי עַל כֵּן חֲזִתִּנּוּן לְאַפָּיךְ כְּחֵיזוּ אַפֵּי רַבְרְבַיָּא וְאִתְרְעֵית לִי:
@41 קַבֵּל כְּעַן יָת תִּקְרֻבְתִּי דְּאִתּוֹתִיאַת לָךְ אֲרֵי רַחִים עֲלַי (קֳדָם) יְיָ וַאֲרֵי אִית לִי כֹלָּא וְאַתְקֵף בֵּהּ וְקַבִּיל:
@42 וַאֲמַר נִטַל וְנֵהָךְ וְאֵיהַךְ לְקָבְלָךְ:
@43 וַאֲמַר לֵהּ רִבּוֹנִי יְדַע אֲרֵי יָנְקַיָּא רַכִּיכִין וְעָנָא וְתוֹרֵי מֵינִקְתָּא עָלָי וּדְחוֹקִנּוּן יוֹמָא חַד וִימוּתוּן כָּל עָנָא:
@44 יְעִבַּר כְּעַן רִבּוֹנִי קֳדָם עַבְדֵּהּ וַאֲנָא אֱדַבֵּר בְּנִיחַ לְרֶגֶל עוֹבַדְתָּא דִּי קֳדָמַי וּלְרֶגֶל יָנְקַיָּא עַד דִּי אֵעוֹל לְוַת רִבּוֹנִי לְשֵׂעִיר:
@45 וַאֲמַר עֵשָׂו אֶשְׁבּוֹק כְּעַן עִמָּךְ מִן עַמָּא דְּעִמִּי וַאֲמַר לְמָא דְנַן אַשְׁכַּח רַחֲמִין בְּעֵינֵי רִבּוֹנִי:
@46 וְתַב בְּיוֹמָא הַהוּא עֵשָׂו לְאָרְחֵהּ לְשֵׂעִיר:
@47 וְיַעֲקֹב נְטַל לְסֻכּוֹת וּבְנָא לֵהּ בֵּיתָא וְלִבְעִירֵהּ עֲבַד מְטַלָּן עַל כֵּן קְרָא שְׁמָא דְאַתְרָא סֻכּוֹת:
@48 וַאֲתָא יַעֲקֹב שְׁלִים קַרְתָּא דִּשְׁכֶם דִּי בְּאַרְעָא דִּכְנָעַן בְּמֵיתֵהּ מִפַּדַּן דַּאֲרָם וּשְׁרָא לָקֳבֵל (אַפֵּי) קַרְתָּא:
@49 וּזְבַן יָת אַחֲסָנַת חַקְלָא דִּי פְרַס תַּמָּן מַשְׁכְּנֵהּ מִידָא דִּבְנֵי חֲמוֹר אֲבוּהִי דִּשְׁכֶם בְּמֵאָה חוּרְפָן:
@50 וַאֲקֵם תַּמָּן מַדְבְּחָא וּפְלַח עֲלוֹהִי קֳדָם אֵל אֱלָהָא דְיִשְׂרָאֵל:
@51 וּנְפָקַת דִּינָה בַּת לֵאָה דִּי יְלִידַת לְיַעֲקֹב לְמֶחֱזֵי בִּבְנַת אַרְעָא:
@52 וַחֲזָא יָתַהּ שְׁכֶם בַּר חֲמוֹר חִוָאָה רַבָּא דְאַרְעָא וּדְבַר יָתַהּ וּשְׁכִיב יָתַהּ וְעַנְיַהּ:
@53 וְאִתְרְעִיאַת נַפְשֵׁהּ בְּדִינָה בַּת יַעֲקֹב וּרְחֵים יָת עוּלֶמְתָּא וּמַלִּיל עַל לִבָּא דְעוּלֶמְתָּא:
@54 וַאֲמַר שְׁכֶם לַחֲמוֹר אֲבוּהִי לְמֵימָר סַב לִי יָת עוּלֶמְתָּא הָדָא לְאִנְתּוּ:
@55 וְיַעֲקֹב שְׁמַע אֲרֵי סָאֵיב יָת דִּינָה בְרַתֵּהּ וּבְנוֹהִי הֲווֹ עִם גֵּיתוֹהִי בְּחַקְלָא וְשָׁתִיק יַעֲקֹב עַד מֵיתֵיהוֹן:
@56 וּנְפַק חֲמוֹר אֲבוּהִי דִּשְׁכֶם לְוַת יַעֲקֹב לְמַלָּלָא עִמֵּהּ:
@57 וּבְנֵי יַעֲקֹב עַלּוּ מִן חַקְלָא כַּד שְׁמָעוּ וְאִתְנְסִיסוּ גֻּבְרַיָּא וּתְקֵיף לְהוֹן לַחֲדָא אֲרֵי קְלָנָא עֲבַד בְּיִשְׂרָאֵל לְמִשְׁכַּב עִם בַּת יַעֲקֹב וְכֵן לָא כָשַׁר לְאִתְעֲבָדָא:
@58 וּמַלִּיל חֲמוֹר עִמְּהוֹן לְמֵימָר שְׁכֶם בְּרִי אִתְרְעִיאַת נַפְשֵׁהּ בִּבְרַתְּכוֹן הָבוּ כְעַן יָתַהּ לֵהּ לְאִנְתּוּ:
@59 וְתִתְחַתְּנוּן בָּנָא בְּנָתֵיכוֹן תִּתְּנוּן לָנָא וְיָת בְּנָתָנָא תִּסְבוּן לְכוֹן:
@60 וְעִמָּנָא תֵּתְבוּן וְאַרְעָא תְּהֵי קֳדָמֵיכוֹן תִּיבוּ וְעֲבִידוּ בַהּ סְחוֹרְתָּא וְאַחֲסִינוּ בַּהּ:
@61 וַאֲמַר שְׁכֶם לַאֲבוּהָא וּלְאַחָהָא אַשְׁכַּח רַחֲמִין בְּעֵינֵיכוֹן וְדִי תֵימְרוּן לִי אֶתֵּן:
@62 אַסְגוּ עָלַי לַחֲדָא מוֹהֲרִין וּמַתְּנָן וְאֶתֵּן כְּמָא דִּי תֵימְרוּן לִי וְהָבוּ לִי יָת עוּלֶמְתָּא:לאִנְתּוּ:
@63 וַאֲתִיבוּ בְנֵי יַעֲקֹב יָת שְׁכֶם וְיָת חֲמוֹר אֲבוּהִי בְּחָכְמְתָא וּמַלִּילוּ דִּי סָאֵב יָת דִּינָה אֲחָתְהוֹן:
@64 וַאֲמָרוּ לְהוֹן לָא נִכּוּל לְמֶעְבַּד פִּתְגָּמָא הָדֵין לְמִתַּן יָת אֲחָתָנָא לִגְבַר דִּי לֵיהּ עָרְלְתָא אֲרֵי חִסּוּדָא הִיא לָנָא:
@65 בְּרַם בְּדָא נִתְפֵּס לְכוֹן אִם תֶּהֱווֹן כְּוָתָנָא לְמִגְזַר לְכוֹן כָּל דְּכוּרָא:
@66 וְנִתַּן יָת בְּנָתָנָא לְכוֹן וְיָת בְּנָתֵיכוֹן נִסַּב לָנָא וְנִתּוּב עִמְּכוֹן וְנֵיהֵי לְעַמָּא חָד:
@67 וְאִם לָא תְקַבְּלוּן מִנָּנָא לְמִגְזָר וּנְדַבֵּר יָת בְּרַתָּנָא וְנֵזֵיל:
@68 וּשְׁפָרוּ פִּתְגָּמֵיהוֹן בְּעֵינֵי חֲמוֹר וּבְעֵינֵי שְׁכֶם בַּר חֲמוֹר:
@69 וְלָא אוֹחַר עוּלֵימָא לְמֶעְבַּד פִּתְגָּמָא אֲרֵי אִתְרְעִי בְּבַת יַעֲקֹב וְהוּא יַקִּיר מִכֹּל בֵּית אֲבוּהִי:
@70 וַאֲתָא חֲמוֹר וּשְׁכֶם בְּרֵהּ לִתְרַע קַרְתְּהוֹן וּמַלִּילוּ עִם אֲנָשֵׁי קַרְתְּהוֹן לְמֵימָר:
@71 גֻּבְרַיָּא הָאִלֵּין שָׁלְמִין אִנּוּן עִמָּנָא וִיתִיבוּן בְּאַרְעָא וְיַעְבְּדוּן בַּהּ סְחוֹרְתָא וְאַרְעָא הָא פְתָיוּת יְדִין קֳדָמֵיהוֹן יָת בְּנָתֵיהוֹן נִסַּב לָנָא לִנְשִׁין וְיָת בְּנָתָנָא נִתֵּן לְהוֹן:
@72 בְּרַם בְּדָא יִתָּפְסוּן לָנָא גּוּבְרַיָּא לְמִתַּב עִמָּנָא לְמֶהֱוֵי לְעַמָּא חָד בְּמִגְזַר לָנָא כָּל דְּכוּרָא כְּמָא דִּי אִנּוּן גְּזִירִין:
@73 גֵּיתֵיהוֹן וְקִנְיָנְהוֹן וְכָל בְּעִירְהוֹן הֲלָא דִּילָנָא אִנּוּן בְּרַם נִתְפֵּס לְהוֹן וִיתִיבוּן עִמָּנָא:
@74 וְקַבִּילוּ מִן חֲמוֹר וּמִן שְׁכֶם בְּרֵהּ כָּל נָפְקֵי תְּרַע קַרְתֵּהּ וּגְזָרוּ כָּל דְּכוּרָא כָּל נָפְקֵי תְּרַע קַרְתֵּהּ:
@75 וַהֲוָה בְיוֹמָא תְלִיתָאָה כַּד תְּקִיפוּ עֲלֵיהוֹן כֵּאבֵיהוֹן וּנְסִיבוּ תְרֵין בְּנֵי יַעֲקֹב שִׁמְעוֹן וְלֵוִי אֲחֵי דִּינָה גְּבַר חַרְבֵּהּ וְעַלּוּ עַל קַרְתָּא דְּיָתְבוּן לְרָחֲצָן וּקְטָלוּ כָּל דְּכוּרָא:
@76 וְיָת חֲמוֹר וְיָת שְׁכֶם בְּרֵהּ קְטָלוּ לְפִתְגַּם דְּחָרֶב וּדְבָרוּ יָת דִּינָה מִבֵּית שְׁכֶם וּנְפָקוּ:
@77 בְּנֵי יַעֲקֹב עַלּוּ לְחַלָּצָא קָטִילַיָּא וּבְזוֹ קַרְתָּא דִּי סָאִיבוּ אֲחָתְהוֹן:
@78 יָת עָנְהוֹן וְיָת תּוֹרְהוֹן וְיָת חֲמָרֵיהוֹן וְיָת דִּי בְקַרְתָּא וְיָת דִּי בְחַקְלָא בְּזוֹ:
@79 וְיָת כָּל נִכְסֵיהוֹן וְיָת כָּל טַפְלְהוֹן וְיָת נְשֵׁיהוֹן שְׁבוֹ וּבְזוֹ וְיָת כָּל דִּי בְבֵיתָא:
@80 וַאֲמַר יַעֲקֹב לְשִׁמְעוֹן וּלְלֵוִי עֲכַרְתּוּן יָתִי לְמִתַּן דְּבָבוּ בֵּינָנָא וּבֵין יָתְבֵי אַרְעָא בִּכְנַעֲנָאָה וּבַפְּרִזָּאָה וַאֲנָא עַם דְּמִנְיַן וְיִתְכַּנְשׁוּן עֲלַי וְיִמְחִנּוּנִי וְאֶשְׁתֵּצֵי אֲנָא וְאֱנַשׁ בֵּיתִי:
@81 וַאֲמָרוּ הַכְנָפְקַת בָּרָא יִתְעֲבֵד (נ''א יַעְבֵּד יָת אַחָתָנָא) לַאֲחָתָנָא:
@82 וַאֲמַר יְיָ לְיַעֲקֹב קוּם סַק לְבֵית אֵל וְתִיב תַּמָן וְעִבֵּד תַּמָן מַדְבְּחָא לֵאלָהָא דְאִתְגְלִי לָךְ בְּמֵעִרְקָךְ מִן קֳדָם עֵשָׂו אָחוּךְ:
@83 וַאֲמַר יַעֲקֹב לֶאֱנַשׁ בֵּיתֵהּ וּלְכֹל דִּי עִמֵּהּ אַעְדוּ יָת טַעֲוַת עַמְמַיָּא דִי בֵינֵיכוֹן וְאִדַכּוּ וְשַׁנּוּ כְּסוּתְכוֹן:
@84 וְנֵקוֹם וְנִסַּק לְבֵית אֵל וְאֶעְבֵּד תַּמָּן מַדְבְּחָא לֵאלָהָא דְקַבִּיל צְלוֹתִי בְּיוֹמָא דְעַקְתִי וַהֲוָה מֵימְרֵהּ בְּסַעְדִי בְּאָרְחָא דִי אֲזָלִית:
@85 וִיהָבוּ לְיַעֲקֹב יָת כָּל טַעֲוַת עַמְמַיָּא דִי בִידֵיהוֹן וְיָת קָדָשַׁיָּא דִי בְאֻדְנֵיהוֹן וְטַּמַּר יָתְהוֹן יַעֲקֹב תְּחוֹת בָּטְמָא דִי עִם שְׁכֶם:
@86 וּנְטָלוּ וַהֲוַת דַּחֲלָא דַיְיָ עַל עַמְמַיָא דִי בְּקִרְוֵי סַחֲרָנֵיהוֹן וְלָא רְדָפוּ בָּתַר בְּנֵי יַעֲקֹב:
@87 וַאֲתָא יַעֲקֹב לְלוּז דִּי בְאַרְעָא דִכְנַעַן הִיא בֵּית אֵל הוּא וְכָל עַמָּא דִי עִמֵּהּ:
@88 וּבְנָא תַמָּן מַדְבְּחָא וּקְרָא לְאַתְרָא אֵל בֵּית אֵל אֲרֵי תַמָּן אִתְגְלֵי לֵהּ יְיָ בְּמֵעִרְקֵהּ מִן קֳדָם אָחוּהִי:
@89 וּמִיתַת דְּבוֹרָה מֵנִקְתָּא דְרִבְקָה וְאִתְקְבָרַת מִלְרַע לְבֵית אֵל בְּשִׁפּוֹלֵי מֵישְׁרָא וּקְרָא שְׁמֵּהּ מֵישַׁר בָּכִיתָא:
@90 וְאִתְגְלִי יְיָ לְיַעֲקֹב עוֹד בְּמֵיתוֹהִי מִפַּדַן אֲרָם וּבָרִיךְ יָתֵהּ:
@91 וַאֲמַר לֵהּ יְיָ שְׁמָךְ יַעֲקֹב לָא יִתְקְרֵי שְׁמָךְ עוֹד יַעֲקֹב אֶלָהֵין יִשְׂרָאֵל יְהֵא שְׁמָךְ וּקְרָא יָת שְׁמֵהּ יִשְׂרָאֵל:
@92 וַאֲמַר לֵהּ יְיָ אֲנָא אֵל שַׁדַּי פּוּשׁ וּסְגֵי עַם וְכִנְשַׁת שִׁבְטִּין יְהֵא מִנָּךְ וּמַלְכִין דְשַׁלִּיטִין בְּעַמְמַיָּא מִנָּךְ יִפְקוּן:
@93 וְיָת אַרְעָא דִי יְהָבִית לְאַבְרָהָם וּלְיִצְחָק לָךְ אֶתְּנִנַּהּ וְלִבְנָיךְ בַּתְרָךְ אֶתֵּן יָת אַרְעָא:
@94 וְאִסְתַּלַּק מֵעִלָּוֹהִי יְקָרָא דַיְיָ בְּאַתְרָא דִי מַלֵּיל עִמֵּהּ:
@95 וַאֲקֵם יַעֲקֹב קַמְתָא בְּאַתְרָא דִי מַלִּיל עִמֵּהּ קָמַת אַבְנָא וְאַסִּיךְ עֲלַהּ נִסּוּכִין וַאֲרִיק עֲלַהּ מִשְׁחָא:
@96 וּקְרָא יַעֲקֹב יָת שְׁמָא דְאַתְרָא דִי מַלִּיל עִמֵּהּ תַּמָּן יְיָ בֵּית אֵל:
@97 וּנְטָלוּ מִבֵּית אֵל וַהֲוָה עוֹד כְּרוּבַת אַרְעָא לְמֵיעַל לְאֶפְרָת וִילִידַת רָחֵל וְקַשִׁיאַת בְּמֵילְדַהּ:
@98 וַהֲוָה בְקַשְׁיוּתַהּ בְּמֵילְדַהּ וַאֲמֶרֶת לַהּ חָיְתָא לָא תִדְחֲלִי אֲרֵי אַף דֵּין לִיךְ בָּר:
@99 וַהֲוָה בְּמִפַּק נַפְשַׁהּ אֲרֵי מִיתַת (נ''י מַיְתָא) וּקְרַת שְׁמֵהּ בַּר דְוָי וַאֲבוּהִי קְרָא לֵהּ בִּנְיָמִין:
@100 וּמִיתַת רָחֵל וְאִתְקְבָרַת בְּאֹרַח אֶפְרָת הִיא בֵּית לָחֶם:
@101 וַאֲקֵים יַעֲקֹב קַמְתָא עַל קְבֻרְתַּהּ הִיא קָמַת קְבֻרְתָּא דְרָחֵל עַד יוֹמָא דֵין:
@102 וּנְטַל יִשְׂרָאֵל וּפְרַס מַשְׁכְּנֵהּ מִלְהַלָא לְמִגְדְלָא דְעֵדֶר:
@103 וַהֲוָה כַּד שְׁרָא יִשְׂרָאֵל בְּאַרְעָא הַהִיא וַאֲזַל רְאוּבֵן וּשְׁכִיב עִם בִּלְהָה לְחֵינָתָא דַאֲבוּהִי וּשְׁמַע יִשְׂרָאֵל וַהֲווֹ בְנֵי יַעֲקֹב תְּרֵי עֲסַר:
@104 בְּנֵי לֵאָה בּוּכְרָא דְיַעֲקֹב רְאוּבֵן וְשִׁמְעוֹן וְלֵוִי וִיהוּדָה וְיִשָׂשׂכָר וּזְבֻלוּן:
@105 בְּנֵי רָחֵל יוֹסֵף וּבִנְיָמִן:
@106 וּבְנֵי בִלְהָה אַמְתָא דְרָחֵל דָּן וְנַפְתָּלִי:
@107 וּבְנֵי זִלְפָּה אַמְתָא דְלֵאָה גָּד וְאָשֵׁר אִלֵּין בְּנֵי יַעֲקֹב דִּי אִתְיְלִידוּ לֵהּ בְּפַדַן אֲרָם:
@108 וַאֲתָא יַעֲקֹב לְוַת יִצְחָק אֲבוּהִי מַמְרֵא קִרְיַת אַרְבַּע הִיא חֶבְרוֹן דִּי דָר תַּמָּן אַבְרָהָם וְיִצְחָק:
@109 וַהֲווֹ יוֹמֵי יִצְחָק מְאָה וּתְמָנָן שְׁנִין:
@110 וְאִתְנְגִיד יִצְחָק וּמִית וְאִתְכְּנִישׁ לְעַמֵהּ סִיב וּשְׂבַע יוֹמִין וּקְבָרוּ יָתֵהּ עֵשָׂו וְיַעֲקֹב בְּנוֹהִי:
@111 וְאִלֵּין תּוּלְדַת עֵשָׂו הוּא אֱדוֹם:
@112 עֵשָׂו נְסִיב יָת נְשׁוֹהִי מִבְּנַת כְּנָעַן יָת עָדָה בַּת אֵילוֹן חִתָּאָה וְיָת אָהֳלִיבָמָה בַּת עֲנָה בַּת צִבְעוֹן חִוָאָה:
@113 וְיָת בָּשְׂמַת בַּת יִשְׁמָעֵאל אֲחָתֵהּ דִנְבָיוֹת:
@114 וִילִידַת עָדָה לְעֵשָׂו יָת אֱלִיפָז וּבָשְׂמַת יְלִידַת יָת רְעוּאֵל:
@115 וְאָהֳלִיבָמָה יְלִידַת יָת יְעוּשׁ וְיָת יַעְלָם וְיָת קֹרַח אִלֵּין בְּנֵי עֵשָׂו דִי אִתְיְלִידוּ לֵהּ בְּאַרְעָא דִכְנָעַן:
@116 וּדְבַר עֵשָׂו יָת נְשׁוֹהִי וְיָת בְּנוֹהִי וְיָת בְּנָתֵהּ וְיָת כָּל נַפְשַׁת בֵּיתֵהּ וְיָת גֵּיתוֹהִי וְיָת כָּל בְּעִירֵהּ וְיָת כָּל קִנְיָנֵהּ דִי קְנָא בְּאַרְעָא דִכְנָעַן וַאֲזַל לְאַרְעָא אוֹחֲרִי מִן קֳדָם יַעֲקֹב אָחוּהִי:
@117 אֲרֵי הֲוָה קִנְיָנְהוֹן סַגִּי מִלְמִתַּב כַּחֲדָא וְלָא יְכִילַת אֲרַע תּוֹתָבוּתְהוֹן לְסוֹבָרָא יָתְהוֹן מִן קֳדָם גֵּיתֵיהוֹן:
@118 וִיתֵיב עֵשָׂו בְּטוּרָא דְשֵׂעִיר עֵשָׂו הוּא אֱדוֹם:
@119 וְאִלֵּין תּוּלְדַת עֵשָׂו אֲבוּהוֹן דֶאֱדוֹמָאֵי בְּטוּרָא דְשֵׂעִיר:
@120 אִלֵּין שְׁמָהַת בְּנֵי עֵשָׂו אֱלִיפַז בַּר עָדָה אִתַּת עֵשָׂו רְעוּאֵל בַּר בָּשְׂמַת אִתַּת עֵשָׂו:
@121 וַהֲווֹ בְּנֵי אֱלִיפָז תֵּימָן אוֹמָר צְפוֹ וְגַעְתָּם וּקְנַז:
@122 וְתִמְנַע הֲוַת לְחֵינָתָא לֶאֱלִיפַז בַּר עֵשָׂו וִילִידַת לֶאֱלִיפַז יָת עֲמָלֵק אִלֵּין בְּנֵי עָדָה אִתַּת עֵשָׂו:
@123 וְאִלֵּין בְּנֵי רְעוּאֵל נַחַת וָזֶרַח שַׁמָּה וּמִזָה אִלֵּין הֲווֹ בְּנֵי בָשְׂמַת אִתַּת עֵשָׂו:
@124 וְאִלֵּין הֲווֹ בְּנֵי אָהֳלִיבָמָה בַת עֲנָה בַּת צִבְעוֹן אִתַּת עֵשָׂו וִילִידַת לְעֵשָׂו יָת יְעוּשׁ וְיָת יַעְלָם וְיָת קֹרַח:
@125 אִלֵּין רַבְרְבֵי בְנֵי עֵשָׂו בְּנֵי אֱלִיפַז בּוּכְרָא דְעֵשָׂו רַבָּא תֵּימָן רַבָּא אוֹמָר רַבָּא צְפוֹ רַבָּא קְנַז:
@126 רַבָּא קֹרַח רַבָּא גַעְתָּם רַבָּא עֲמָלֵק אִלֵּין רַבְרְבֵי אֱלִיפַז בְּאַרְעָא דֶאֱדוֹם אִלֵּין בְּנֵי עָדָה:
@127 וְאִלֵּין בְּנֵי רְעוּאֵל בַּר עֵשָׂו רַבָּא נַחַת רַבָּא זֶרַח רַבָּא שַׁמָה רַבָּא מִזָּה אִלֵּין רַבְרְבֵי רְעוּאֵל בְּאַרְעָא דֶאֱדוֹם אִלֵין בְּנֵי בָשְׂמַת אִתַּת עֵשָׂו:
@128 וְאִלֵּין בְּנֵי אָהֳלִיבָמָה אִתַּת עֵשָׂו רַבָּא יְעוּשׁ רַבָּא יַעְלָם רַבָּא קֹרַח אִלֵּין רַבְרְבֵי אָהֳלִיבָמָה בַּת עֲנָה אִתַּת עֵשָׂו:
@129 אִלֵּין בְּנֵי עֵשָׂו וְאִלֵּין רַבְרְבָנֵיהוֹן הוּא אֱדוֹם:
@130 אִלֵּין בְּנֵי שֵׂעִיר חוֹרָאָה יָתְבֵי דְּאַרְעָא לוֹטָן וְשׁוֹבָל וְצִבְעוֹן וַעֲנָה:
@131 וְדִישׁוֹן וְאֵצֶר וְדִישָׁן אִלֵּין רַבְרְבֵי חוֹרָאֵי בְּנֵי שֵׂעִיר בְּאַרְעָא דֶאֱדוֹם:
@132 וַהֲווֹ בְנֵי לוֹטָן חוֹרִי וְהֵימָם וַאֲחָתֵהּ דְלוֹטָן תִּמְנָע:
@133 וְאִלֵּין בְּנֵי שׁוֹבָל עַלְוָן וּמָנַחַת וְעֵיבָל שְׁפוֹ וְאוֹנָם:
@134 וְאִלֵּין בְּנֵי צִבְעוֹן וְאַיָּה וַעֲנָה הוּא עֲנָה דִּי אַשְׁכַּח יָתּ גִּבָּרַיָּא בְּמַדְבְּרָא כַּד הֲוָה רָעֵי יָת חֲמָרַיָּא לְצִבְעוֹן אֲבוּהִי:
@135 וְאִלֵּין בְּנֵי עֲנָה דִּשֹׁן וְאָהֳלִיבָמָה בַּת עֲנָה:
@136 וְאִלֵּין בְּנֵי דִישָׁן חֶמְדָן וְאֶשְׁבָּן וְיִתְּרָן וּכְרָן:
@137 אִלֵּין בְּנֵי אֵצֶר בִּלְהָן וְזַעֲוָן וַעֲקָן:
@138 אִלֵּין בְּנֵי דִישָׁן עוּץ וַאֲרָן:
@139 אִלֵּין רַבְרְבֵי חוֹרָאָה רַבָּא לוֹטָן רַבָּא שׁוֹבָל רַבָּא צִבְעוֹן רַבָּא עֲנָה:
@140 רַבָּא דִּשֹׁן רַבָּא אֵצֶר רַבָּא דִישָׁן אִלֵּין רַבְרְבֵי חוֹרָאָה לְרַבְרְבָנֵיהוֹן בְּאַרְעָא דְשֵׂעִיר:
@141 וְאִלֵּין מַלְכַיָּא דִי מְלִיכוּ בְּאַרְעָא דֶאֱדוֹם קֳדָם דִּי מְלַךְ מַלְכָּא לִבְנֵי יִשְׂרָאֵל:
@142 וּמְלַךְ בֶּאֱדוֹם בֶּלַע בַּר בְּעוֹר וְשׁוּם קַרְתֵּהּ דִּנְהָבָה:
@143 וּמִית בָּלַע וּמְלַךְ תְּחוֹתוֹהִי יוֹבָב בַּר זֶרַח מִבָּצְרָה:
@144 וּמִית יוֹבָב וּמְלַךְ תְּחוֹתוֹהִי חֻשָׁם מֵאַרְעָא דָרוֹמָא:
@145 וּמִית חֻשָׁם וּמְלַךְ תְּחוֹתוֹהִי הֲדַד בַּר בְּדַד דִקְטִיל יָת מִדְיָנָאֵי בְּחַקְלָא דְמוֹאָב וְשׁוּם קַרְתֵּהּ עֲוִית:
@146 וּמִית הֲדָד וּמְלַךְ תְּחוֹתוֹהִי שַׂמְלָה מִמַשְׂרֵקָה:
@147 וּמִית שַׂמְלָה וּמְלַךְ תְּחוֹתוֹהִי שָׁאוּל מֵרְחוֹבוֹת דְעַל פְּרָת:
@148 וּמִית שָׁאוּל וּמְלַךְ תְּחוֹתוֹהִי בַּעַל חָנָן בַּר עַכְבּוֹר:
@149 וּמִית בַּעַל חָנָן בַּר עַכְבּוֹר וּמְלַךְ תְּחוֹתוֹהִי הֲדַר וְשׁוּם קַרְתֵּהּ פָּעוּ וְשׁוּם אִתְּתֵהּ מְהֵיטַבְאֵל בַּת מַטְּרֵד בַת מְצָרֵף דַּהֲבָא:
@150 וְאִלֵּין שְׁמָהַת רַבְרְבֵי עֵשָׂו לְזַרְעֲיָתְהוֹן לְאַתְרֵיהוֹן בִּשְׁמָהַתְהוֹן רַבָּא תִמְנָע רַבָּא עַלְוָה רַבָּא יְתֵת:
@151 רַבָּא אָהֳלִיבָמָה רַבָּא אֵלָה רַבָּא פִּינֹן:
@152 רַבָּא קְנַז רַבָּא תֵימָן רַבָּא מִבְצָר:
@153 רַבָּא מַגְדִיאֵל רַבָּא עִירָם אִלֵּין רַבְרְבֵי אֱדוֹם לְמוֹתְבָנְהוֹן בְּאַרְעָא אַחֲסַנְתְּהוֹן הוּא עֵשָׂו אֲבוּהוֹן דֶאֱדוֹמָאֵי: פפפ:

@1 **וישלח יעקב מלאכים.** מלאכים ממש: **ארצה שעיר.** לארץ שעיר, כל תיבה שצריכה למ''ד בתחלתה הטיל לה הכתוב ה''א בסופה:
@2 **גרתי.** לא נעשיתי שר וחשוב אלא גר, אינך כדאי לשנוא אותי על ברכות אביך שברכני (לעיל כז כט) הוה גביר לאחיך, שהרי לא נתקימה בי. דבר אחר גרתי בגימטריא תרי''ג, כלומר עם לבן הרשע גרתי ותרי''ג מצות שמרתי ולא למדתי ממעשיו הרעים:
@3 **ויהי לי שור וחמור.** אבא אמר לי (כז כח) מטל השמים ומשמני הארץ, זו אינה לא מן השמים ולא מן הארץ: **שור וחמור.** דרך ארץ לומר על שורים הרבה שור. אדם אומר לחברו בלילה קרא התרנגול, ואינו אומר קראו התרנגולים: **ואשלחה להגיד לאדוני.** להודיע שאני בא אליך: **למצא חן בעיניך.** שאני שלם עמך ומבקש אהבתך:
@4 **באנו אל אחיך אל עשו.** שהיית אומר אחי הוא, אבל הוא נוהג עמך כעשו הרשע, עודנו בשנאתו:
@5 **ויירא ויצר.** ויירא שמא יהרג, ויצר לו אם יהרוג הוא את אחרים:
@6 **המחנה האחת והכהו.** מחנה משמש לשון זכר ולשון נקבה. (תהלים כז ג) אם תחנה עלי מחנה, הרי לשון נקבה, (לג ח) המחנה הזה, לשון זכר. וכן יש שאר דברים משמשים לשון זכר ולשון נקבה, (לעיל יט כג) השמש יצא על הארץ, (תהלים יט ז) מקצה השמים מוצאו, הרי לשון זכר. (מ''ב ג כב) והשמש זרחה על המים, הרי לשון נקבה. וכן רוח (איוב א יט) והנה רוח גדולה באה, הרי לשון נקבה, (שם) ויגע בארבע פנות הבית, הרי לשון זכר, (מ''א יט יא) ורוח גדולה וחזק מפרק הרים, הרי לשון זכר ולשון נקבה. וכן אש (במדבר טז לה) ואש יצאה מאת ה', לשון נקבה. (תהלים קד ד) אש לוהט, לשון זכר: **והיה המחנה הנשאר לפלטה.** על כרחו כי אלחם עמו. התקין עצמו לשלשה דברים לדורון, לתפלה ולמלחמה. לדורון להלן (פסוק כא) ותעבור המנחה על פניו. לתפלה (פסוק ט) אלהי אבי אברהם. למלחמה והיה המחנה הנשאר לפלטה:
@7 **ואלהי אבי יצחק.** ולהלן הוא אומר (לא מב) ופחד יצחק, ועוד מהו שחזר והזכיר שם המיחד, היה לו לכתוב האומר אלי שוב לארצך וגו' . אלא כך אמר יעקב לפני הקדוש ברוך הוא שתי הבטחות הבטחתני אחת בצאתי מבית אבי מבאר שבע, שאמרת לי (כח יג) אני ה' אלהי אברהם אביך ואלהי יצחק, ושם אמרת לי (שם טו) ושמרתיך בכל אשר תלך. ובבית לבן אמרת לי (לא ג) שוב אל ארץ אבותיך ולמולדתך ואהיה עמך, ושם נגלית אלי בשם המיחד לבדו, שנאמר (לא ג) ויאמר ה' אל יעקב שוב אל ארץ אבותיך וגו' , בשתי הבטחות האלו אני בא לפניך:
@8 **קטנתי מכל החסדים.** נתמעטו זכיותי על ידי החסדים והאמת שעשית עמי, לכך אני ירא, שמא משהבטחתני נתלכלכתי בחטא ויגרום לי להמסר ביד עשו: **ומכל האמת.** אמתת דבריך, ששמרת לי כל ההבטחות שהבטחתני: **כי במקלי.** לא היה עמי לא כסף ולא זהב ולא מקנה אלא מקלי לבדו. ומדרש אגדה נתן מקלו בירדן ונבקע הירדן:
@9 **מיד אחי מיד עשו.** מיד אחי שאין נוהג עמי כאח אלא כעשו הרשע:
@10 **היטב איטיב.** היטב בזכותך, איטיב בזכות אבותיך: **ושמתי את זרעך כחול הים.** והיכן אמר לו כן, והלא לא אמר לו אלא (שם כח יד) והיה זרעך כעפר הארץ. אלא שאמר לו (כח טו) כי לא אעזבך עד אשר אם עשיתי את אשר דברתי לך, ולאברהם אמר (כב יז) הרבה ארבה את זרעך ככוכבי השמים וכחול אשר על שפת הים:
@11 **הבא בידו.** ברשותו, וכן (במדבר כא כו) ויקח את כל ארצו מידו. ומדרש אגדה מן הבא בידו אבנים טובות ומרגליות, שאדם צר בצרור ונושאם בידו. דבר אחר מן הבא בידו מן החלין, שנטל מעשר, כמה דאת אמר (כח כב) עשר אעשרנו לך, והדר לקח מנחה:
@12 **עזים מאתים ותישים עשרים.** מאתים עזים צריכות עשרים תישים, וכן כלם, הזכרים כדי צורך הנקבות. ובבראשית רבה (עו ז) דורש מכאן לעונה האמורה בתורה, הטילים בכל יום, הפועלים שתים בשבת, החמרים אחת בשבת, הגמלים אחת לשלשים יום, הספנים אחת לששה חדשים. ואיני יודע לכון המדרש הזה בכוון. אך נראה בעיני שלמדנו מכאן שאין העונה שוה בכל אדם אלא לפי טורח המטל עליו, שמצינו כאן שמסר לכל תיש עשרה עזים, וכן לכל איל, לפי שהם פנוים ממלאכה, דרכן להרבות בתשמיש לעבר עשר נקבות, ובהמה משנתעברה אינה מקבלת זכר, ופרים שעוסקין במלאכה לא מסר לזכר אלא ארבע נקבות, ולחמור שהולך בדרך רחוקה שתי נקבות לזכר, ולגמלים שהולכים דרך יותר רחוקה נקבה אחת לזכר:
@13 **גמלים מיניקות** וט' **שלשים.** ובניהם עמהם. ומדרש אגדה ובניהם בנאיהם, זכר כנגד נקבה, ולפי שצנוע בתשמיש לא פרסמו הכתוב: **ועירים.** חמורים זכרים:
@14 **עדר עדר לבדו.** כל מין ומין לעצמו: **עברו לפני.** דרך יום או פחות, ואני אבא אחריכם: **ורוח תשימו.** עדר לפני חברו מלא עין, כדי להשביע עינו של רשע ולתוהו על רבוי הדורון:
@15 **למי אתה.** שלמי אתה, מי שולחך, ותרגומו דמן את: **ולמי אלה לפניך.** ואלה שלפניך שלמי הם, למי המנחה הזאת שלוחה. למ''ד משמשת בראש התבה במקום של, כמו (לעיל לא מג) וכל אשר אתה רואה לי הוא, שלי הוא, (תהלים כד א) לה' הארץ ומלואה, של ה':
@16 **ואמרת לעבדך ליעקב.** על ראשון ראשון ועל אחרון אחרון, ששאלת (פסוק יז. יח) למי אתה, לעבדך ליעקב אני, ותרגומו דעבדך דיעקב, וששאלת (פסוק יז. יח) ולמי אלה לפניך, מנחה היא שלוחה וגו' : **והנה גם הוא.** יעקב:
@18 **אכפרה פניו.** אבטל רגזו וכן (ישעיה כח יח) וכפר בריתכם את מות, (שם מז יא) לא תוכלי כפרה. ונראה בעיני שכל כפרה שאצל עוון וחטא ואצל פנים כלן לשון קנוח והעברה הן, ולשון ארמי הוא הרבה בתלמוד (ב''מ כד א) וכפר ידה, (גיטין נו א) בעי לכפורי ידה בההוא גברא, וגם בלשון המקראנקראים המזרקים של קדש (עזרא א י) כפורי זהב, על שם שהכהן מקנח ידיו בהן בשפת המזרק:
@19 **על פניו.** כמו לפניו, וכן (ירמיה ו ז) חמס ושד ישמע בה על פני תמיד, וכן (ישעיה סה ג) המכעסים אתי על פני. ומדרש אגדה על פניו אף הוא שרוי בכעס, שהיה צריך לכל זה:
@20 **ואת אחד עשר ילדיו.** ודינה היכן היתה, נתנה בתבה ונעל בפניה שלא יתן בה עשו עיניו, ולכך נענש יעקב שמנעה מאחיו שמא תחזירנו למוטב, ונפלה ביד שכם: **יבק.** שם הנהר:
@21 **את אשר לו.** הבהמות והמטלטלין, עשה עצמו כגשר, נוטל מכאן מניח כאן:
@22 **ויותר יעקב.** שכח פכים קטנים וחזר עליהם: **ויאבק איש.** מנחם פרש ויתעפר איש, לשון אבק, שהיו מעלים עפר ברגליהם על ידי נענועם. ולי נראה שהוא לשון ויתקשר, ולשון ארמי הוא, בתר דאביקו בה, ואבק לה מיבק, לשון עניבה, שכן דרך שנים שמתעצמים להפיל איש את רעהו שחובקו ואובקו בזרועותיו. ופירשו רבותינו זכרונם לברכה שהוא שרו של עשו:
@23 **ויגע בכף ירכו.** קלית הירך התקוע בקלבוסית קרוי כף, על שם שהבשר שעליה כמין כף של קדרה: **ותקע.** נתקעקעה ממקום מחברתה, ודומה לו (ירמיה ו ח) פן תקע נפשי ממך, לשון הסרה. ובמשנה לקעקע ביצתן, לשרש שרשיהן:
@24 **כי עלה השחר.** וצריך אני לומר שירה ביום: **ברכתני.** הודה לי על הברכות שברכני אבי, שעשו מערער עליהן:
@26 **לא יעקב.** לא יאמר עוד שהברכות באו לך בעקבה וברמיה כי אם בשררה ובגלוי פנים, וסופך שהקדוש ברוך הוא נגלה עליך בבית אל ומחליף את שמך, ושם הוא מברכך, ואני שם אהיה ואודה לך עליהן, וזהו שכתוב (הושע יב ה) וישר אל מלאך ויכל בכה ויתחנן לו, בכה המלאך ויתחנן לו, ומה נתחנן לו (שם) בית אל ימצאנו ושם ידבר עמנו, המתן לי עד שידבר עמנו שם, ולא רצה יעקב, ועל כרחו הודה לו עליהן, וזהו (פסוק ל) ויברך אותו שם, שהיה מתחנן להמתין לו ולא רצה: **ועם אנשים.** עשו ולבן: **ותוכל.** להם:
@27 **למה זה תשאל.** אין לנו שם קבוע, משתנין שמותינו, הכל לפי מצות עבודת השליחות שאנו משתלחים:
@29 **ויזרח לו השמש.** לשון בני אדם הוא, כשהגענו למקום פלוני האיר לנו השחר, זהו פשוטו. ומדרש אגדה ויזרח לו לצרכו, לרפאות את צלעתו, כמה דתימא (מלאכי ג כ) שמש צדקה ומרפא בכנפיה, ואותן שעות שמיהרה לשקוע בשבילו כשיצא מבאר שבע, מהרה לזרוח בשבילו: **והוא צלע.** והוא היה צולע כשזרחה השמש:
@30 **גיד הנשה.** ולמה נקרא שמו גיד הנשה, לפי שנשה ממקומו ועלה, והוא לשון קפיצה, וכן (ירמיה נא ל) נשתה גבורתם, וכן (לקמן מא נא) כי נשני אלהים את כל עמלי:
@32 **ואת לאה וילדיה אחרנים.** אחרון אחרון חביב:
@33 **עבר לפניהם.** אמר אם יבא אותו רשע להלחם, ילחם בי תחלה:
@34 **ויחבקהו.** נתגלגלו רחמיו כשראהו משתחוה כל השתחואות הללו: **וישקהו.** נקוד עליו, ויש חולקין בדבר הזה בברייתא דספרי (בהעלותך סט) , יש שדרשו נקדה זו לומר שלא נשקו בכל לבו. אמר ר' שמעון בן יוחאי הלכה היא בידוע שעשו שונא ליעקב, אלא שנכמרו רחמיו באותה שעה ונשקו בכל לבו:
@35 **מי אלה לך.** מי אלה להיות שלך:
@37 **נגש יוסף ורחל.** בכלן האמהות נגשות לפני הבנים, אבל ברחל יוסף נגש לפניה, אמר אמי יפת תאר, שמא יתלה בה עיניו אותו רשע, אעמד כנגדה ואעכבנו מלהסתכל בה, מכאן זכה יוסף לברכת (מט כב) עלי עין:
@38 **מי לך כל המחנה.** מי כל המחנה אשר פגשתי שהוא שלך, כלומר למה הוא לך. ופשוטו של מקרא [נאמר] על מוליכי המנחה. ומדרשו כתות של מלאכים פגע, שהיו דוחפין אותו ואת אנשיו, ואומרים להם של מי אתם, והם אומרים להם של עשו, והן אומרים הכו הכו, ואלו אומרים הניחו בנו של יצחק הוא, ולא היו משגיחים עליו, בן בנו של אברהם הוא, ולא היו משגיחים, אחיו של יעקב הוא, אומרים להם אם כן משלנו אתם:
@39 **יהי לך אשר לך.** כאן הודה לו על הברכות:
@40 **אל נא.** אל נא תאמר לי כן: **אם נא מצאתי חן בעיניך ולקחת מנחתי מידי כי על כן ראיתי פניך** וגו' **.** כי כדאי והגון לך שתקבל מנחתי על אשר ראיתי פניך, והן חשובין לי כראית פני המלאך שראיתי שר שלך, ועוד על שנתרצית למחול סרחני. ולמה הזכיר לו ראית המלאך, כדי שיתירא המנו ויאמר ראה מלאכים ונצול, איני יכול לו מעתה: **ותרצני.** נתפיסת לי, וכן כל רצון שבמקרא לשון פיוס, אפיימינ''ט בלע''ז (ויקרא כב כ) כי לא לרצון יהיה לכם, הקרבנות באות לפיס ולרצון, וכן (משלי י לב) שפתי צדיק ידעון רצון, יודעים לפיס ולרצות:
@41 **ברכתי.** מנחתי, מנחה זו הבאה על ראית פנים ולפרקים אינה באה אלא לשאילת שלום, וכל ברכה שהיא לראית פנים, כגון להלן (מז י) ויברך יעקב את פרעה, (מ''ב יח לא) עשו אתי ברכה, דסנחריב. וכן (ש''ב ח י) לשאל לו לשלום ולברכו, דתועי מלך חמת, כלם לשון ברכת שלום הן שקורין בלע''ז שלוצי''ר [לשאול בשלום], אף זו ברכתי מו''ן שלו''ד : **אשר הבאת לך.** לא טרחת בה, ואני יגעתי להגיעה עד שבאה לידך: **חנני.** נו''ן ראשונה מדגשת לפי שהיא משמשת במקום שתי נוני''ן, שהיה לו לומר חננני, שאין חנן בלא שתי נונין, והשלישית לשמוש כמו עשני, זבדני: **יש לי כל.** כל ספוקי, ועשו דבר בלשון גאוה (פסוק ט) יש לי רב, יותר ויותר מכדי צרכי:
@42 **נסעה.** כמו (תהלים קל ב) שמעה, שהוא כמו שמע, אף כאן נסעה כמו נסע, והנו''ן יסוד בתבה. ותרגומו טול ונהך, עשו אמר ליעקב נסע מכאן ונלך: **ואלכה לנגדך.** בשוה לך, טובה זו אעשה לך שאאריך ימי מהלכתי ללכת לאט כאשר אתה צריך, וזהו לנגדך, בשוה לך:
@43 **עלות עלי.** הצאן והבקר שהן עלות מטלות עלי לנהלן לאט: **עלות.** מגדלות עולליהן, לשון (איכה ב יא) עולל ויונק, (ישעיה סה כ) עול ימים, (שמואל א' ו י) ושתי פרות עלות, ובלע''ז אינפנטיי''ש **ודפקום יום אחד.** ליגעם בדרך במרוצה, ומתו כל הצאן: **ודפקום.** כמו (שה''ש ה ב) קול דודי דופק, נוקש בדלת:
@44 **יעבר נא אדני.** אל תאריך ימי הליכתך, עבור כפי דרכך ואף אם תתרחק: **אתנהלה.** אתנהל, ה''א יתרה כמו (לעיל יח כא) ארדה, (במדבר ט ח) אשמעה: **לאטי.** לאט שלי, לשון נחת (ישעיה ח ו) ההולכים לאט, (ש''ב יח ה) לאט לי לנער. לאטי הלמ''ד מן היסוד ואינה משמשת, אתנהל נחת שלי: **לרגל המלאכה.** לפי צורך הליכת רגלי המלאכה המטלת עלי להוליך: **ולרגל הילדים.** לפי רגליהם שהם יכולים לילך: **עד אשר אבא אל אדני שעירה.** הרחיב לו הדרך, שלא היה דעתו ללכת אלא עד סכות. אמר אם דעתו לעשות לי רעה ימתין עד בואי אצלו, והוא לא הלך. ואימתי ילך, בימי המשיח, שנאמר (עובדיה א כא) ועלו מושעים בהר ציון לשפט את הר עשו. ומדרשי אגדה יש לפרשה זו רבים:
@45 **ויאמר למה זה.** תעשה לי טובה זו שאיני צריך לה: **אמצא חן בעיני אדני.** ולא תשלם לי עתה שום גמול:
@46 **וישב ביום ההוא עשו לדרכו.** עשו לבדו וארבע מאות איש שהלכו עמו נשמטו מאצלו אחד אחד. והיכן פרע להם הקדוש ברוך הוא, בימי דוד, שנאמר (ש''א ל יז) כי אם ארבע מאות איש נער אשר רכבו על הגמלים:
@47 **ויבן לו בית.** שהה שם שמונה עשר חדש, קיץ וחרף וקיץ. סכות קיץ, בית חורף, סכות קיץ:
@48 **שלם.** שלם בגופו, שנתרפא מצליעתו. שלם בממונו, שלא חסר כלום מכל אותו דורון. שלם בתורתו, שלא שכח תלמודו בבית לבן: **עיר שכם.** כמו לעיר, וכמוהו (רות א יט) עד בואנה בית לחם: **בבאו מפדן ארם.** כאדם האומר לחברו יצא פלוני מבין שני אריות ובא שלם, אף כאן ויבא שלם מפדן ארם, מלבן ומעשו שנזדוגו לו בדרך:
@49 **קשיטה.** מעה. אמר רבי עקיבא כשהלכתי לכרכי הים היו קורין למעה קשיטה (ותרגומו חרפן, טובים, חריפים בכל מקום, כגון עובר לסוחר) :
@50 **ויקרא לו אל אלהי ישראל.** לא שהמזבח קרוי אלהי ישראל, אלא על שם שהיה הקדוש ברוך הוא עמו והצילו קרא שם המזבח על שם הנס, להיות שבחו של מקום נזכר בקריאת השם, כלומר מי שהוא אל הוא הקדוש ברוך הוא הוא לאלהים לי ששמי ישראל, וכן מצינו במשה (שמות יז טו) ויקרא שמו ה' נסי, לא שהמזבח קרוי ה', אלא על שם הנס קרא שם המזבח, להזכיר שבחו של הקדוש ברוך הוא, ה' הוא נסי. ורבותינו דרשוהו שהקדוש ברוך הוא קראו ליעקב אל. ודברי תורה (ירמיה כג כט) כפטיש יפצץ סלע, מתחלקים לכמה טעמים, ואני לישב פשוטו ושמועו של מקרא באתי:
@51 **בת לאה.** ולא בת יעקב, אלא על שם יציאתה נקראת בת לאה, שאף היא יצאנית היתה, שנאמר (ל טז) ותצא לאה לקראתו (ועליה משלו המשל (יחזקאל טז מד) כאמה בתה) :
@52 **וישכב אתה.** כדרכה: **ויענה.** שלא כדרכה:
@53 **על לב הנערה.** דברים המתישבין על הלב, ראי אביך בחלקת שדה קטנה כמה ממון בזבז, אני אשאך ותקני העיר וכל שדותיה:
@57 **וכן לא יעשה.** לענות את הבתולות, שהאמות גדרו עצמן מן העריות על ידי המבול:
@58 **חשקה.** חפצה:
@62 **מהר.** כתבה:
@63 **במרמה.** בחכמה: **אשר טמא.** הכתוב אומר שלא היתה רמיה, שהרי טמא את דינה אחותם:
@64 **חרפה הוא.** שמץ פסול הוא אצלנו, הבא לחרף חברו הוא אומר לו ערל אתה, או בן ערל. חרפה בכל מקום גדוף:
@65 **נאות לכם.** נתרצה לכם, לשון (מ''ב יב ט) ויאותו: **להמל.** להיות נמול, אינו לשון לפעול אלא לשון להפעל:
@66 **ונתנו.** נו''ן שניה מדגשת, לפי שהיא משמשת במקום שתי נוני''ן ונתננו: **ואת בנתיכם נקח לנו.** אתה מוצא בתנאי שאמר חמור ליעקב ובתשובת בני יעקב לחמור שתלו החשיבות בבני יעקב, לקח בנות שכם את שיבחרו להם ובנותיהם יתנו להם לפי דעתם, דכתיב ונתנו את בנותינו, לפי דעתנו, ואת בנותיכם נקח לנו, ככל אשר נחפוץ. וכשדברו חמור ושכם בנו אל יושבי עירם הפכו הדברים (פסוק כא) את בנתם נקח לנו לנשים ואת בנתינו נתן להם, כדי לרצותם שיאותו להמול:
@71 **שלמים.** בשלום ובלב שלם: **והארץ הנה רחבת ידים.** כאדם שידו רחבה וותרנית, כלומר לא תפסידו כלום, פרקמטיא הרבה באה לכאן ואין לה קונים:
@72 **בהמול.** בהיות נמול:
@73 **אך נאותה להם.** לדבר זה, ועל ידי כן ישבו אתנו:
@75 **שני בני יעקב.** בניו היו, ואף על פי כן נהגו עצמן שמעון ולוי, כשאר אנשים שאינם בניו, שלא נטלו עצה המנו: **אחי דינה.** לפי שמסרו עצמן עליה נקראו אחיה: **בטח.** שהיו כואבים. ומדרש אגדה בטוחים היו על כחו של זקן:
@77 **על החללים.** לפשט את החללים:
@79 **חילם.** ממונם וכן (דברים ח יז) עשה לי את החיל הזה, (במדבר כד יח) וישראל עשה חיל, (תהלים מט יא) ועזבו לאחרים חילם: **שבו.** לשון שביה לפיכך טעמו מלרע:
@80 **עכרתם.** לשון מים עכורים, אין דעתי צלולה עכשיו. ואגדה, צלולה היתה החבית ועכרתם אותה, מסורת היתה ביד כנענים שיפלו ביד בני יעקב, אלא שהיו אומרים (שמות כג ל) עד אשר תפרה ונחלת את הארץ, לפיכך היו שותקין: **מתי מספר.** אנשים מועטים:
@81 **הכזונה.** הפקר: **את אחותנו.** ית אחתנא:
@82 **קום עלה.** לפי שאחרת בדרך נענשת ובא לך זאת מבתך:
@83 **הנכר.** שיש בידכם משלל שלשכם: **והטהרו.** מעבודה זרה: **והחליפו שמלתיכם.** שמא יש בידכם כסות של עבודה זרה:
@85 **האלה.** מין אילן סרק: **עם שכם.** אצל שכם:
@86 **חתת.** פחד:
@88 **אל בית אל.** הקדוש ברוך הוא בבית אל גלוי שכינתו בבית אל. יש תבה חסרה בי''ת המשמשת בראשה, כמו (ש''ב ט ד) הנה הוא בית מכיר בן עמיאל, כמו בבית מכיר, (להלן לח יא) בית אביך כמו בבית אביך: **נגלו אליו האלהים.** במקומות הרבה יש שם אלהות ואדנות בלשון רבים, כמו (להלן לט כ) אדני יוסף, (שמות כב יד) אם בעליו עמו, ולא נאמר בעלו, וכן אלהות שהוא לשון שופט ומרות נזכר בלשון רבים, אבל אחד מכל שאר השמות לא תמצא בלשון רבים:
@89 **ותמת דברה.** מה ענין דבורה בבית יעקב, אלא לפי שאמרה רבקה ליעקב (כז מה) ושלחתי ולקחתיך משם, שלחה דבורה אצלו לפדן ארם לצאת משם, ומתה בדרך. מדברי רבי משה הדרשן למדתיה: **מתחת לבית אל.** העיר יושבת בהר ונקברה ברגלי ההר: **תחת האלון.** בשפולי מישרא, שהיה מישור מלמעלה בשפוע ההר והקבורה מלמטה, ומישור של בית אל היו קורין לו אלון. ואגדה נתבשר שם באבל שני, שהגד לו על אמו שמתה. ואלון בלשון יוני אחר. ולפי שהעלימו את יום מותה, שלא יקללו הבריות הכרס שיצא ממנו עשו, אף הכתוב לא פרסמו:
@90 **עוד.** פעם שני במקום הזה, אחד בלכתו ואחד בשובו: **ויברך אתו.** ברכת אבלים:
@91 **לא יקרא שמך עוד יעקב.** לשון אדם הבא במארב ועקבה אלא לשון שר ונגיד:
@92 **אני אל שדי.** שאני כדאי לברך, שהברכות שלי: **פרה ורבה.** על שם שעדין לא נלד בנימין ואף על פי שכבר נתעברה ממנו: **גוי.** בנימין: **גוים.** מנשה ואפרים שעתידים לצאת מיוסף, והם במנין השבטים: **ומלכים.** שאול ואיש בשת שהיו משבט בנימין, שעדין לא נלד. (ופסוק זה דרשו אבנר כשהמליך איש בשת, ואף השבטים דרשוהו וקרבו בנימין, דכתיב (שופטים כא א) איש ממנו לא יתן את בתו לבנימן לאשה, וחזרו ואמרו אלמלא היה עולה מן השבטים לא היה הקדוש ברוך הוא אומר ליעקב ומלכים מחלציך יצאו) : **גוי וקהל גוים.** שגוים עתידים בניו להעשות כמנין הגוים שהם שבעים אמות, וכן כל הסנהדרין שבעים. דבר אחר שעתידים בניו להקריב אסור במות כגוים בימי אליהו:
@95 **במקום אשר דבר אתו.** איני יודע מה מלמדנו:
@97 **כברת הארץ.** מנחם פרש לשון כביר, רבוי, מהלך רב. ואגדה בזמן שהארץ חלולה ומנקבת ככברה שהניר מצוי, הסתו עבר, והשרב עדין לא בא. ואין זה פשוטו של מקרא, שהרי בנעמן מצינו (מ''ב ה יט) וילך מאתו כברת ארץ. ואומר אני שהוא שם מדת קרקע כמו מהלך פרסה או יותר, כמו שאתה אומר (ישעיה ה י) צמדי כרם, (לעיל לג יט) חלקת השדה, כך במהלך אדם נותן שם מדה כברת ארץ:
@98 **כי גם זה.** נוסף לך על יוסף. ורבותינו דרשו עם כל שבט נלדה תאומה, ועם בנימין נלדה תאומה יתרה:
@99 **בן אוני.** בן צערי: **בנימין.** נראה בעיני לפי שהוא לבדו נלד בארץ כנען, שהיא בנגב כשאדם בא מארם נהרים, כמו שנאמר (במדבר לג מ) בנגב בארץ כנען, (לעיל יב ט) הלוך ונסוע הנגבה: **בנימין.** בן ימין, לשון (תהלים פט יג) צפון וימין אתה בראתם, לפיכך הוא מלא:
@103 **בשכן ישראל בארץ ההוא.** עד שלא בא לחברון אצל יצחק ארעוהו כל אלה: **וישכב.** מתוך שבלבל משכבו מעלה עליו הכתוב כאלו שכבה. ולמה בלבל וחלל יצועו, שכשמתה רחל נטל יעקב מטתו שהיתה נתונה תדיר באהל רחל ולא בשאר אהלים ונתנה באהל בלהה, בא ראובן ותבע עלבון אמו, אמר אם אחות אמי היתה צרה לאמי, שפחת אחות אמי תהא צרה לאמי, לכן בלבל: **ויהיו בני יעקב שנים עשר.** מתחיל לענין ראשון משנלד בנימין נשלמה המטה, ומעתה ראוים להמנות, ומנאן. ורבותינו דרשו ללמדנו בא שכלן שוין, וכלן צדיקים, שלא חטא ראובן:
@104 **בכור יעקב.** אפלו בשעת הקלקלה קראו בכור: **בכור יעקב.** בכור לנחלה, בכור לעבודה, בכור למנין, ולא נתנה בכורה ליוסף אלא לענין השבטים שנעשה לשני שבטים:
@108 **ממרא.** שם המישור: **קרית הארבע.** שם העיר ממרא קרית הארבע אל מישור של קרית ארבע. ואם תאמר היה לו לכתוב ממרא הקרית ארבע, כן דרך המקרא בכל דבר ששמו כפול, כגון זה, וכגון בית לחם, אבי עזר, בית אל, אם הוצרך להטיל בו ה''א נותנה בראש התבה השניה (ש''א טז א) בית הלחמי, (שופטים ו כד) בעפרת אבי העזרי, (מ''א טז לד) בנה חיאל בית האלי:
@110 **ויגוע יצחק.** אין מקדם ומאחר בתורה, מכירתו של יוסף קדמה למיתתו של יצחק שתים עשרה שנה, שהרי כשנלד יעקב היה יצחק בן ששים שנה, שנאמר (לעיל כה כו) ויצחק בן ששים שנה וגו' , ויצחק מת בשנת מאה ועשרים ליעקב, אם תוציא ששים ממאה ושמונים שנה, נשארו מאה ועשרים, ויוסף נמכר בן שבע עשרה שנה, ואותה שנה שנת מאה ושמונה ליעקב. כיצד, בן ששים ושלש נתברך, וארבע עשרה שנה נטמן בבית עבר, הרי שבעים ושבע, וארבע עשרה עבד באשה, ובסוף ארבע עשרה נלד יוסף, שנאמר (לעיל ל כה) ויהי כאשר ילדה רחל את יוסף וגו' , הרי תשעים ואחת, ושבע עשרה עד שלא נמכר יוסף הרי מאה ושמנה. (עוד מפורש מן המקרא משנמכר יוסף עד שבא יעקב מצרימה עשרים ושתים שנה, שנאמר (להלן מא מו) ויוסף בן שלשים שנה וגו' , ושבע שנים שובע ושנתים רעב הרי עשרים ושתים, וכתיב ימי שני מגורי שלשים ומאת שנה נמצא יעקב במכירתו מאה ושמונה) :
@112 **עדה בת אילון.** היא (לעיל כו לד) בשמת בת אילון, ונקראת בשמת על שם שהיתה מקטרת בשמים לעבודה זרה: **אהליבמה.** היא יהודית, והוא כנה שמה יהודית לומר שהיא כופרת בעבודה זרה כדי להטעות את אביו: **בת ענה בת צבעון.** אם בת ענה לא בת צבעון, ענה בנו של צבעון, שנאמר (פסוק כד) ואלה בני צבעון ואיה וענה, מלמד שבא צבעון על כלתו אשת ענה ויצאת אהליבמה מבין שניהם והודיעך הכתוב שכלן בני ממזרות היו:
@113 **בשמת בת ישמעאל.** ולהלן קורא לה (כח ט) מחלת. מצינו באגדת מדרש ספר שמואל (פרק יז) שלשה מוחלין להן עונותיהם גר שנתגיר, והעולה לגדלה, והנושא אשה, ולמד הטעם מכאן, לכך נקראת מחלת שנמחלו עונותיה: **אחות נביות.** על שם שהוא השיאה לו משמת ישמעאל נקראת על שמו:
@115 **ואהליבמה ילדה** וגו' **.** קרח זה ממזר היה ובן אליפז היה, שבא על אשת אביו אל אהליבמה אשת עשו שהרי הוא מנוי עם (פסוק טז) אלופי אליפז בסוף הענין:
@116 **וילך אל ארץ.** לגור באשר ימצא:
@117 **ולא יכלה ארץ מגוריהם.** להספיק מרעה לבהמות שלהם. ומדרש אגדה (פסוק ו) מפני יעקב אחיו, מפני שטר חוב של גזרת (טו יג) כי גר יהיה זרעך, המטל על זרעו של יצחק, אמר אלך לי מכאן, אין לי חלק לא במתנה שנתנה לו הארץ הזאת, ולא בפרעון השטר. ומפני הבושה, שמכר בכורתו:
@119 **ואלה.** התולדות שהולידו בניו עכשיו משהלך לשעיר:
@122 **ותמנע היתה פילגש.** להודיע גדלתו של אברהם כמה היו תאבים לדבק בזרעו. תמנע זו בת אלופים היתה, שנאמר (פסוק כב) ואחות לוטן תמנע, ולוטן מאלופי יושבי שעיר היה, מן החורים שישבו בה לפנים, אמרה איני זוכה להנשא לך, הלואי ואהיה פילגש. ובדברי הימים מונה אותה (דברי הימים א' א לו) בבניו של אליפז, מלמד שבא על אשתו של שעיר ויצאה תמנע מביניהם, וכשגדלה נעשית פילגשו, וזהו ואחות לוטן תמנע, ולא מנאה עם בני שעיר שהיתה אחותו מן האם ולא מן האב:
@125 **אלה אלופי בני עשו.** ראשי משפחות:
@130 **ישבי הארץ.** שהיו יושביה קודם שבא עשו לשם. ורבותינו דרשו שהיו בקיאין בישובה של ארץ, מלא קנה זה לזיתים מלא קנה זה לגפנים, שהיו טועמין העפר ויודעים אי זו נטיעה ראויה לה:
@134 **ואיה וענה.** וי''ו יתרה, והוא כמו איה וענה, והרבה יש במקרא (דניאל ח יג) תת וקדש וצבא מרמס, (תהלים עו ז) נרדם ורכב וסוס: **הוא ענה.** האמור למעלה (פסוק כ) שהוא אחיו של צבעון וכאן הוא קורא אותו בנו, מלמד שבא צבעון על אמו והוליד את ענה: **את הימם.** פרדים, הרביע חמור על סוס נקבה וילדה פרד, והוא היה ממזר והביא פסולין לעולם. ולמה נקרא שמם ימים, שאימתן מטלת על הבריות, דאמר רבי חנינא מימי לא שאלני אדם על מכת פרדה לבנה וחיה (והלא קא חזינן דחיה, אל תקרי וחיה אלא וחיתה, כי המכה לא תרפא לעולם) . ולא הזקק לכתוב לנו משפחות החורי אלא מפני תמנע, ולהודיע גדלת זרע אברהם, כמו שפרשתי למעלה (פסוק יב) :
@141 **ואלה המלכים** וגו' **.** שמנה היו וכנגדן העמיד יעקב ובטל מלכות עשו בימיהם, ואלו הן שאול, ואיש בשת, דוד, ושלמה, רחבעם, אביה, אסא, יהושפט. ובימי יורם בנו כתיב (מ''ב ח כ) בימיו פשע אדום מתחת יד יהודה וימלכו עליהם מלך, ובימי שאול כתיב (מ''א כב מח) ומלך אין באדום נצב מלך:
@143 **יובב בן זרח מבצרה.** בצרה מערי מואב היא, שנאמר (ירמיה מח כד) ועל קריות ועל בצרה וגו' , ולפי שהעמידה מלך לאדום, עתידה ללקות עמהם, שנאמר (ישעיה לד ו) כי זבח לה' בבצרה:
@145 **המכה את מדין בשדה מואב.** שבא מדין על מואב למלחמה, והלך מלך אדום לעזור את מואב. ומכאן אנו למדים שהיו מדין ומואב מריבים זה עם זה, ובימי בלעם עשו שלום להתקשר על ישראל:
@149 **בת מי זהב.** שהיה אומר מהו זהב, עשיר היה ואין זהב חשוב בעיניו לכלום:
@150 **ואלה שמות אלופי עשו.** שנקרא על שם מדינותיהם לאחר שמת הדר ופסקה מהם מלכות. והראשונים הנזכרים למעלה, הם שמות תולדותם, וכן מפורש בדברי הימים (דברי הימים א' א נא) וימת הדד ויהיו אלופי אדום אלוף תמנע וגו' :
@153 **מגדיאל.** היא רומי:
@154 **חזון עובדיה.** מאי שנא עובדיה לאדום ולא ניבא נבואה אחרת אמרו חכמי' עובדיה גר אדומי היה אמר הקב"ה מהם ובהם אביא עליהם יבא עובדיה שדר בין שני רשעים אחאב ואיזבל ולא למד ממעשיהם ויפרע מעשו הרשע שדר בין שני צדיקים יצחק ורבק' ולא למד ממעשיה':
@155 **הנה קטן נתתיך.** כלפי שקראו אביו בנו הגדול ואמו בנה הגדול אמר הקב"ה לפני קטן הוא רבותינו דרשו קטן שלא היה להם לא כתב ולא לשון: **בזוי.** שלא היו מעמידין מלך בן מלך:
@156 **שוכני בחגוי סלע.** סומך על משענת אבותיו אברהם ויצחק והם לא יועילו לו, חגוי כמו ( ישעיה יט ) והיתה אדמת יהודה למצרים לחגא ברייטיינ"א בלעז ואל תתמה על וי"ו של חגוי שהיא כוי"ו של קצוי ( תהלים סה ) וכוי"ו של כמטחוי ( בראשית כא ) שאין יסוד בתיבה אלא טי"ת וחי"ת:
@158 **באו לך.** עליך: **איך נדמיתה.** למה נרדמתה דומם עד שגנבו כל רצונם: **הלא בוצרים ישאירו עוללות.** ואלה לא ישאירו לך כלום כי יחפשוך ויגלו וידרשו מצפוניך:
@159 **נבעו.** תרגום יונתן איתגליין ולשון ארמית נבעו נתבקשו וכן אם תבעיון בעיו ( ישעיה כא ):
@160 **עד הגבול שלחוך.** אותם שהבטיחוך לעזרה באו עמך ולווך עד גבול ארצך עד הספר ששם באו עליך למלחמה ובזאת השיאוך והצליחו: **יכלו לך.** לפתותך לצאת ושבו מאחריך: **לחמך ישימו מזור תחתיך.** אף מאכלך שם לך אחיך יעקב למזור שנתן לך לחם ונזיד עדשים ועל ידו בזית הבכורה: **מזור.** חולי:
@162 **וחתו גבוריך תימן.** יחתו ויפחדו לנוס אל ארץ ישמעאל וי"ת ויתברון גברך יתבי ארעא דרומא: **למען יכרת.** כל איש גבור: **מהר עשו מקטל.** מרוב הרג שיבא עליכם:
@163 **מחמס אחיך יעקב.** בשביל חמס שעשית ליעקב:
@164 **ביום עמדך מנגד.** שלא באת לעזור לו: **גם אתה כאחד מהם.** אעלה אני עליך כאילו אתה מן הבאים עליהם:
@165 **ואל תרא ביום אחיך.** לא היה לך ( להביט ) ולעמוד מנגד: **ביום נכרו.** ביום הסגירו ביד אויב הוא הבבליים וכן הוא אומר בשאול ( שמואל א כג ) נכר אותו אלהים בידי הסגיר אותו בידי:
@166 **ואל תשלחנה בחילו.** אל תשלחנה ידך בנכסיו כן תרגם יונתן ומקרא קצר הוא וצריך להוסיף עליו ידך:
@167 **ואל תעמוד על הפרק.** מקום שהבורחים יוצאים דרך שם לימלט ובלשון לע"ז קוראים אותו טרו"ג ( אל תעמוד על הפרק, מכאן שאסור להפסיק בק"ש בין פרק לפרק הג"ה דר"ע ):
@169 **כאשר שתיתם על הר קדשי.** כמה דחדיתון על מחת טורא דקודשי: **ולעו.** כתרגומו ויסתלעמון ל' מהומה ושממון וטירוף דעת אישטורדישו"ן בלע"ז:
@170 **את מורשיהם.** נכסי עממיא דהוו מחסנין להון:
@171 **כי ה' דבר.** והיכן דבר ( במדבר כד ) וירד מיעקב והאביד שריד וגו':
@172 **וירשו הנגב.** ישראל שהיו יושבין בדרומה של ארץ ישראל ירשו את הר עשו שהוא במצר דרום ובני השפלה ירשו את ארץ פלשתים ואת הר אפרים ואת הר שומרון: **ובנימין את הגלעד.** ובני מנשה שהיתה ארץ גלעד שלהם יפשטו להם מהלאה לגבולותיה של ארץ ישראל במזרחה:
@173 **וגלות החל הזה.** תרגם יונתן עמא הדין, החל לשון חיל כמו ( ישעיה לו ) ויבא ירושלמה בחיל כבד דרבשקה אלא שזה חסר יו"ד ויש עוד לפרש החל הזה גלות הגיא הזה: **לבני ישראל אשר כנענים עד צרפת.** גלות אשר הוא מבני ישראל שגלו מעשרת השבטים לארץ כנענים עד צרפת: **וגלות ירושלים אשר בספרד.** שהם מבני יהודה אשר גלו לספרד הם ירשו את ערי הנגב שבדרומה של ארץ ישראל ואומרי' הפותרים צרפת הוא המלכות שקורין פרנצ"א בלע"ז ספרד תרגם יונתן אספמיא:
@174 **ועלו.** שרי ישראל מושיעים בהר ציון: **לשפוט את הר עשו.** ליפרע מהר עשו אשר עשו לישראל לשפוט יושטיציי"ר בלע"ז: **הר עשו.** י"ת כרכא רבא דעשו: **והיתה לה' המלוכה.** לימדך שאין מלכותו שלימה עד שיפרע מעמלק:

@8 **החסדים.** הם מה שעשה לו ה' יתעלה מהטובות ומה שייעד לו מהם.
@8 **האמת.** הוא מה שקיים לו השם יתעלה מיעודיו הטובים כמו שביארנו זה במה שקדם.
@8 **במקלי.** בזולת שום קניין לא היה לי זולת מקלי שהייתי נושא בדרך כדי להמלט מהכלבים וממה שידמה להם.
@9 **והכני אם על בנים.** ר"ל שמא יכני באופן שלא ישאיר לי שריד וזה שיכה אם על בנים וימית הכל יחד ויחס ההכאה לו בעבור היותם כלם קניינו או הוא מושך עצמו ואחר עמו כמו שכתב החכם אבן עזרא והרצון בו והכני והכה אם על בנים. והביאור הראשון נראה לנו יותר.
@18 **אכפרה פניו.** אעביר אפו.
@22 **ויאבק.** כמנהג האנשים המתאבקים להפיל האחד מהם האחר.
@23 **ותקע כף ירך יעקב.** סרה ממקומה באופן שמצא עצמו צולע על ירכו כשהשכים.
@26 **שרית עם אלהים.** נחשבת שר עם המלאכים לחוזק השגחתך וקורבת מדרגתך מהם.
@29 **ויזרח לו השמש כאשר עבר.** כי כבר יזרח השמש במקום אחר ולא יזרח אז במקום השני המתחלף לו באורך וזה מבואר למי שעיין עיון מעט בחכמת התכונה.
@30 **כף הירך.** הוא הבשר המתעגל סביב העצם הנקרא האנ"קא המותא. והוא מחזיק בעצם ההוא כמו שיקיף כף היד במה שיחזיק בו.
@30 **גיד הנשה.** הוא שם הגיד אשר על הכף ההוא לצד חיצוני הגוף ועניינו מפורסם.
@34 נקוד על **וישקהו** להורות שאין נשיקתו בלב שלם אבל היה עניינה ממוצע בין הנשיקה ובין העדר הנשיקה. ולזה היתה זאת התיבה ממוצעת בין הכתיבה והמחק.
@38 **מי לך כל המחנה הזה אשר פגשתי.** רוצה לומר לך כל המחנה אשר פגשתי. והרצון בזה כי מהאנשים ישוה לך כל המחנה הזה אשר פגשתי. וזה כי האדם יתן הדורון כדי שיהיה לו ממקבלו גמול ורצה בזה שאי אפשר שישולם לו גמול על דורון נפלא כזה או פירושו מה יבקשו לך כל המחנה אשר פגשתי והם מוליכי המנחה כאלו לא היה מאמין עשו שתהיה המנחה שלוחה לו להפלגתא.
@40 **פני אלהים.** פני השרים גדולים. או ירצה בזה פני מלאכי ה' להודיעו שהוא נביא כדי שיראה מהזיק לו.
@43 **עלות.** מניקות העוללים.
@44 **לאטי.** לנחת שלי.
@45 **אציגה.** אניחה ואעזבה.
@48 **שלם.** הוא מענין שלום. והרצון בו שכבר בא בשלום ולא ארע לו שום מקרה רע עד בואו בשכם.
@49 **קשיטה.** היא מעה לפי מה שבארו רז"ל וכבר יהיו מהם שש בדינר והנה קנה אותם בדמים מעטים כמו שתראה כי לא היו כי אם ד' סלעים וד' מעות.
@50 **ויקרא לו אל אלהי ישראל.** ר"ל לפי מה שאחשב שכבר קרה לו שבאה לו נבואה שם מהשם יתעלה שהוא אלהי ישראל כטעם אולי יקרה יי' לקראתי וזה ממה שירה שהמקום ההוא שבנה בו המזבח היה נכון שתדבק בו ההשפעה האלהית. והנה לא נזכרה זאת הנבואה כי אולי לא היה בה דבר מחודש או היא הנבואה שזכר אחר זה שבאה לו שם והוא שאמר לו השם יתע' קום עלה ביתאל ואפשר שיהיה הרצון בו שהוא קרא שם המזבח אל אלהי ישראל כמו שקרא משה שם המזבח יי' נסי וכמו שקרא למקום אל ביתאל במה שנזכר אחר זה וזה הפירוש הוא פירוש החכם א"ע. והביאור הראשון הוא יותר נאות לפי מה שאחשוב כי לא תמצא לאכו' בנין מזבח אם לא מצד שהגיעה שם הנבואה כדי שתגיע גם כן בעתיד כמו שקדם. והנה אפשר לפי זאת הכונה שיהיה פירוש ויקרא ויקרא לו אל אלהי ישראל וכבר קרה לו שהגיעה שם לו מהש' יתע' ולזה בנה שם מזבח.
@52 **ויענה.** אפשר שבא עליה שלא כדרכה כמו שאמרו ז"ל כי אנשי המקומות ההם היו מתגאלים מאד בעריות או אפשר שיהיה הענוי להיותה בתולה כמו שנאמר בנערה המאורסה על דבר אשר ענה ובאונס נערה בתולה אמר תחת אשר ענה.
@71 **שלמים הם אתנו.** הוא מעניין שלום והרצון בו שכבר הם בשלום עמהם או יהיה מעניין שלמות ומעלה כמו שאמרו לאברהם נשיא אלהים אתה בתוכנו. ולזה ראוי שישמעו לחמול להם כל זכר כדי שיוכלו להתחתן עמהם באופן שיהיו לעם אחד.
@71 **רחבת ידים.** רחבת המקומות ולזה לא יצר לנו המקום בסבתם.
@80 **מתי מספר.** עם מעט שיספר בקלות.
@81 **הכזונה יעשה את אחותינו.** קבלנו בזה מהרב אדונינו אבינו נ"ע שהם אמרו ליעקב וכי יעשה שכם אחותינו כזונה שלא יהיה נהרג עליה וזה שבן נח היה מצווה על העריות ונהרג עליהם ופטור בגלוי עריות הזונה כמו שאמרו ז"ל מאימת פטור עלה מכי קרו לה רביתה דפלגיא.
@83 **אלהי הנכר.** האך האלילים שלקחו מבית מכם והיו שם גם כן טף שכם ונשיהם שהיו מחזיקים באלו האלילי' והנה צוה יעקב לביתו שישתדלו להסיר אלהי הנכר מכל אשר אתם. והנה אחשב כי הנזמים אשר באזניהם היו מוכנים בעת ההיא לעשות אלילים לחשבם שתהיה להם בזה סגלה הלא תראה שהעגל שעשו ישראל נעשה מהנזמים אשר באזניהם וכן נעשה מהנזמים אשר באזנם אפוד גדעון. ולה לקח יעקב הנזמים אשר באזניהם וטמן אותם עם אלהי הנכר די שלא יהנו מהם סבה בעינה אשר מנעה התורה שלא נהנה מע"ז.
@88 **אל בית אל.** כמו אל בבית אל כמה שפיר הר"ש.
@95 **ויסך עליה נסך.** הוא מעניין נסכים והנה עשה זה הנסך לכבוד השם יתעלה.
@97 **כברת ארץ.** אחשוב שיהיה הרצון בו בחלק מהארץ שהיא ככברה לספונותו והוא החלק הנעבד והנה היה סמוך לאפרתה שלא היה בינו ובין אפרתה כי אם שדות העיר וגניה וכרמיה וכזה בעניין נעמן. וילך מאתו כברת ארץ. ר"ל שלא הרחיק נעמן אלא שיצא משדות העיר וגניה וכרמיה. ולזה השיגו גחזי קרוב מהעיר.
@99 **בן אוני.** בן אכלי. כמו לא אכלתי באוני.
@99 **ואביו קרא לו בנימן.** הטעם בן דרום כי הדרום יקרא ימין בלשוננו וזה כי הוא לבדו נולד בארץ ישראל שהיא לפאת דרום מהמקום אשר נולדו שם שאר בני יעקב.
@101 **קבורתה.** כמו קברה ר"ל שאין הרצון בו פועל הקבור' כי לא יתכן שיצב מצבה על פועל הקבור אבל הציב מצבה על המקום שהיה שם קברה וכן לא ידע איש את קבורתו כמו קברו וזה הוא אצלינו הרצון במה שכתב א"ע קבורתה וקברה שוים.
@116 **וילך אל ארץ.** ר"ל שהלך לבקש ארץ נאות לו ולמקנהו.
@125 **אלוף.** נשיא וגדול. מענין נשיאות ומלכות כמו הורי יהודה.
@134 ואו **ואיה** נוספת וכמוהו נרדם ורכב וסוס. והרצון בו נרדם רכב וסוס.
@134 **הימים.** הם הפרדים וקראם כן לפי שאימתם מוטלת על הבריות.

@1 **וישלח יעקב מלאכים וגומר עד ויבא יעקב שלם:**
@1 **ביאור דברי הספור:**
@1 **זכר** שכבר שלח יעקב שלוחים ילכו לפניו אל עשו אחיו להשתדל להשלים עמו כפי מה שאפשר ולזה אמר להם כה תאמרון לאדוני לעשו כה אמר עבדך יעקב עם לבן גרתי ואחר עד עתה והצליחני הש' ית' בביתו ונתן לי שור וחמור צאן ועבד ושפחה ותכף שהגיעוני אלו הקניינים נפרדתי מלבן ושלחתי להגיד לאדוני למצא חן בעיניך וכל זה היה לפרסם לעשו כי הוא לא היה שונא לו ולא ירצה להתרחק ממנו ולהעלים ממנו ענייניו אך רצונו להתנהג עמו כאח עם שכבר פרסם לו בזה המאמר שיעקב אינו עמו במדרגת אדון כמו שברכהו יצחק אכן הוא לו במדרגת עבד וזה ממה שיש בו רושם נפלא להסיר ממנו שנאת עשו ואולם אמר יעקב לשלוחיו כה תאמרון לאדוני לעשו כדי שתתישב בלבם שעשו הוא אדון ליעקב וידברו עמו בדרך מוסר העבד כמו שכת' החכם אבן עזרא והנה באו השלוחים והודיעו ליעקב שכבר עשו שליחותם ושעשו הוא הולך לקראתו וארבע מאות איש עמו ויירא יעקב לו מאד שיגיע לו נזק מעשו וייצר לו מאד אע"פ שכבר הש' הבטיחו שישמרהו בכל אשר ילך הנה ירא יעקב שמא איננו ראוי לכמו זאת ההשגחה הנפלאה ויעדר ממנו מפני זה הייעוד הטוב וזה כי הייעוד הטוב אינו חוזר כשאין בו תנאי בעצמות. ואולם כשיהיה בו תנאי בעצמות יסור היעוד בסור התנאי בעניין הברכות הכתובות בתורה כשיתנהג במצות התורה למקיימי' מצותה וכבר תמצא שאמ' ירמיהו רגע אדבר על גוי ועל ממלכה לנתוש ולנתוץ ולהאביד ושב הגוי ההוא מדעתו אשר דברתי אליו ונחמתי על הרעה אשר חשבתי לעשות לו ורגע אדבר על גוי ועל ממלכה לבנות ולנטוע ועשה הרעה בעיני לבלתי שמוע קולי ונחמתי על הטוב אשר אמרתי להטיב לו הנה ביאר לך שהייעוד הטוב והייעוד הרע חוזרים בשנוי המקבלים מטוב לרע או מרע לטוב. ולפעמים יהיה היעוד הטוב באופן שיחוייב שיהיה עמו תנאי ואם לא נזכר והוא כשיעד ה' בטוב מתמיד בכל מקום ובכל זמן כי זה יחוייב ממנו שיהיה שם נאי והוא שיהיה המקבל באופן שתדבק בו ההשגחה האלהית כי אי אפשר שיגיע כמו זה הטוב התמידיי בזולת זה האופן כמו שקדם וכבר ביארנו זה כלו בששי מספר מלחמו' יי' ושם ביארנו שהייעוד הרע יש בו תנאי. ואם לא נזכר והתרנו שם הספקות הנופלות בזה וכאשר שער יעקב זה ירא שמא יגרום החטא וימנע ממנו זה הטוב מצד היותו בלתי ראוי שתדבק בו ההשגחה האלהית בכמו זה האופן הנפלא והיה לו עוד לירא שישחת זרעו לסב' שני' וזה כי זה היה אפשר בזולת בטול היעוד כי כבר אפשר שיקיים לו הש' זרע אחר ולזה השתדל יעקב להציל מה שיוכל וחלק העם אשר עמו וקנייניו לשני מחנות שאם יבא עשו אל המחנה האחת והכהו אולי תתקרר דעתו וינצל השני והתפלל יעקב לשם יתעל' ואמר אלהי אבי אברהם ואלהי אבי יצחק השם האומר אלי שוב לארצך ולמולדתך וטיבה עמך הנני בלתי ראוי לכל החסדים והאמת אשר עשית את עבדך. כי במקלי עברתי את הירדן הזה בבאי לבית לבן ועתה בשובי הייתי לשני מחנות ייטב נא בעיניך שתצילני מיד אחי עשו פן יבא וישחיתני מבלי השאיר לי שריד ואתה הבטחתני שתטיב עמי ותשי' זרעי כחול הים אשר לא יספר מרוב. ועם כל זה הנני מפחד מעשו להיותי בלתי ראוי לכמו זאת ההשגחה הנפלאה. וילן שם יעקב בלילה ההוא ולקח מהבא בידו מהקנינים מנחה לעשו אחיו לפייס דעתו ולהשלי' עמו ושם בכל עדר מהזכרים מה שיספיק לעדר הוא בטבע וזה שהוא שלחו לו עזים מאתים ותישים עשרים רחלים מאתים ואיליםעשרים גמלים מניקות ובניהם שלשים פרות ארבעים ופרים עשרה אתונות עשרים ועירי' עשרה ושם כל עדר לבדו וצוה לשים ריוח בין עדר ובין עדר כדי להשביע עינו של עשו כדי שתראה המנחה יותר גדולה וצוה לכל אחד מההולכים אחרי העדרים שיאמר לעשו כשישאלהו למי הוא ולמי מה שלפניו יענו לו לעבדך ליעקב מנחה היא שלוחה לאדוני לעשו גם הנה עבדך יעקב אחרינו. ואולם עשה זה יעקב לשכך חמתו במה שיראה מהפלגת המנחה ומהפלגת הכנע יעקב לו. ותעבור המחנה אצל פני יעקב ר"ל שהוא היה רואה אותה בעברה והיה רואה שעשו כמו שצוה אותם לתת ריוח בין עדר ובין עדר ויעקב לן בלילה ההוא במחנה וקם יעקב בלילה ההוא ויעבר נשיו וביו ושפחותיו וכל קנייניו את מעבר יבוק אחר שעבר הוא בראשונה לנסות עומק המים ומאי זה מקום יכשר יותר שיעבור ונשאר יעקב לבדו להעביר לו קצת קניניו שנשארו שם ויישן שם ונראה לו בנבואה מלאך יי' כאלו הוא איש ולעוצם דבקתו בו וקורבת מדרגת ממנו נדמה לו שהוא נאבק עמו עם שיעקב כבר ראה עניין זה ההתאבקות מפני טרדת דמיונו בעניין עשו וחשב להמציא תחבולות להפילו אם יקום עליו להכותו כי אין מראין לאדם אלא מהרהורי לבו והנה ארך זמן התאבקות עד עלות השחר כי אז הגיע העת שהיה מקיץ יעקב לפי מנהגו והנה נדמה לו שנגע בכף ירכו ותקע כף ירך יעקב בהאבקו עמו ואמר ליעקב שישלחהו כי עלה השחר והגיע העת הראוי ליעקב שיפנה לעסקיו ולא רצה יעקב להתיר הקשר אשר ביניהם אם לא יברכהו תחלה ואמ' אליו המלאך שלא יקרא שמו עוד יעקב כי אם ישראל כי הוא שרר עם מלאכי הש' עד שמדרגתו קרוב' למדרגתם ולא נלאה כחו בזה ויהיה שר ג"כ עם אנשים ולא ינוצח ובזה היה ליעקב יעוד מה שלא ינצחהו עשו וישאל יעקב את המלא' מה שמו המורה על מהותו כדי שיושג לו מהותו בשלמותו והודיע אותו המלאך כי מהותו נעלם מאד אי אפשר שישיגהו האדם. וכבר ביארנו זה בראשון ממלחמו' הש' ויברך אותו זה המלאך שם וכאשר הקיץ קרא יעקב שם המקום ההוא פנואל כי ראיתי אלהים פנים אל פנים ותנצל נפשי והנה זרח לו השמש כאשר עבר את פנואל והוא צולע על ירכו מפני מה שקרהו על כן צוו בני ישראל בהר סיני שלא יאכלו החלק מגיד הנשה שהוא על כף הירך אבל מה שהיה ממנו בזולת המקום הזה לא נאסר להם לאכלו וזה הצווי היה לפרסם ענין זאת הנבואה הנפלאה שהגיעה ליעקב אשר מרוב הדבקות שהיה לו במלאך קרה לו זה המקרה וזה כי התאמנה בנבואה היא מפנו' התורה ואולם אמרנו שנצטוו בה ישראל על הר סיני כי רתוה לא נתנה פעמים כמו שאמרו ז"ל בפרק גיד הנשה וכבר ביארנו סבת זה אל ביאור פריה ורביה בפרשת בראשית ולזה יהיה:
@1 **השרש** האחד מזאת המצוה שאינה נוהגת אלא במה שמינו מותר באכילה ממה שיש לו כף כגון בהמה טהורה וחיה טהורה ואולם העוף אין לו כף. ר"ל שיהיה עוגל את העצם ומחזיק בו ולזה איננו נוהג בו וזה כי ענין זה המאמר הוא שמן הבעל חי הנאכלים צריך שנזהר שלא נאכל גיד הנשה וזה מבואר בנפשו וזה כי מניעת החלק מה מהדבר לא תהיה בעצמות אם לא היה הדבר ההוא מותר וזה שאם היה הדבר ההוא אסור לא תהיה המניעה לחלק בעצמות אבל תחיה לכל ולזה יתבאר שהוא נוהג בשליל ובכל אחד מהירכות כי בכל אחת כף ונוהג בנבלות וטרפות שלהם ובבהמת קדשים לפי שמינם מותר באכילה. והנה נסתפק לחכמי התלמוד אם מה שאמר הכתוב אשר על כף הירך ירצה בו שיהיה לו כף לפי המנהג הטבעי או לפי המציאות וה שאם רצה בה מי שיש לו כף על המנהג הטבעי יהיה נוהג בבהמה וחיה אע"פ שלא ימצא להם כף בזה התאר כי הם בטבע שימצא להם כף ולא יהיה נוהג בעוף אף על פי שימצא לו כף בזה התואר כי הוא בטבע שלא ימצא לו כף עוגל העצם ומחזיק בו ואם רצה בזה במי שיש לו כף. לפי המציאות הנה יהיה העניין בזה בהפך ולזה יהיה העניין באלו ספק וספקא דאורייתא לחומרא:
@1 **והשרש** השני הוא שלא מנעה תורה מגיד הנשה אלא מה שהיה ממנו על כף הירך לא מה שהיה ממנו בזולת המקום ההוא וזה מבואר ממה שאמר הכתוב אשר על כף הירך ואולם חכמינו ז"ל לעשות משמרת למשמרת התורה אסרו הגיד הנשה כלו והצריכו לחטט אחריו הנה נתבארו אלו השרשים בשלמות בפרק גיד הנשה. וכבר התבאר במה שזכרנו בשרשים הכוללים שגיד הנשה הוא מותר בהנאה וראוי שתדע שאעפ"י שלשון אכילה בא בתורה בגיד הנשה לא יהיה מתנו שיהיה בו כזית כי כבר מנעתהו התורה כביאור היה גדול או קטן ויראה לי שאם רסק וכתש מהחלק האסור מגיד הנשה לא יהיה מחוייב באכלו מהמרוסק אם לא יהיה בו כזית שהרי לא נקרא אז גיד הנשה וזה יתבאר ממה שאמרו בפרק אלו הלוקין במי שרסק תשע נמלות. והנה הסכמנו שיהיה זה ההתאבקות בעת השינה לפי שהוא בלתי אפשר שיראה לאד' מלאך השם בזה האופן בהשתמש בכחותיו הגופיות וכבר הודיענו הרב המורה שכבר נשמט במקומות רבים זכר היות הנבוא' בחלום או במראה להשענו שכל הנבואה היא בזה התואר. ולזה לא זכר בזה המקום שתהיה זאת הנבואה בחלום או במראה ואם יספק אדם עליהו ויאמר איך יתכן שישאר לו מזה זה הרושם בזה שהיה צולע על ירכו כאשר הקיץ נאמר לו שזה אפשר אצלנו לאחת משתי סבות. אמנם האחת היא שכבר נראה התפעל כלי הנפש מהדמיונים שיהיו לאדם בעת השינה לפי שהדמיונים ההם יניעו כלי הנפש הנעה מה וזה שכבר תראה שיחלום האדם והוא שוכב עם אשה ויראה קרי כאלו היה זה פועל שלם בהקיץ וכן תמצא שיחלום האדם שהוא נופל ממקום גבוה ויתנועעו מפני זה איבריו בעת השינה תנועה נפלאה עד שיקיץ בסבת זאת התנועה וימצא עצמו שכבר התנועע תנועה נפלאה וזה מבואר מאד מהחוש. ולזאת הסבה אפשר יקרה לו כשראה כשנקעה כף ירכו בחלום שישאר לו מזה רושם במקום ההוא מצד התנועה תקרא לו אז ולזה אפשר שקרה שמצא עצמו צולע על ירכו כאשר הקיץ. והסבה השנית הוא שכבר יתעורר לפעמים הדמיון מהדברים אשר יתפעל בהם האדם בעת השינה ולזה יקחו הרופאים ראיה חזקה על החולי מחלומו' החולה והמשל שאם יגע הישן בדבר קר יחלום שהוא במים קרים או שכבר ירדה עליו השלג והכפור וממה שידמה לזה. ואם יגע הישן בדבר חם יחלום שהוא באש או שהשמש מכה עליו ומה שדימה לזה וזה דבר אין ספק בו כי החוש יעיד על זה ולזאת הסב' תמצא שכאשר יגבר המותר הזרעי באדם ויתעורר לצאת יחלום שהוא שוכב עם אשה ולזאת הסבה בעינה הנה כשיתחדש לאדם כאב מה בעת השינה יחלום שכבר הוכה במקום ההוא בסבת ריב היה לו עם אדם אחר מה בחלומו וזה ממה שיקראה ג"כ הרב' לפי מה שהושג לנו בחוש. ובהיות העניין כן הנה היה אפשר שקרה ליעקב בסבת העמל שעמל בהעברת כל אשר לו בנחל שנתחדש לו כאב בכף הירך בעת השינה ונדמה לו מפני זה בחלומו של נבואה שיתאבק עם זה האיש ושתקע כף ירכו בהאבקו עמו לפי התאבקו' הנרא' לו והנ' היה זה לפי מה שזכרנו להתאבקו' הנראה לו בעת השינה ג' סבות האחת מהם היא חוזק הדבקו' אשר היה לו עם זה המלאך. והשני' מה ששוטטה מחשבתו בהקיץ להמציא תחבולות להפיל עשו אם יבא עליו להכותו. והשלישית הכאב שנתחדש לו בעת שינה בכף הירך. עוד ספר שכבר נשא יעקב עיניו וירא והנה עשו בא וארבע מאות איש עמו ויחץ את הילדים על לאה ועל רחל ועל שתי השפחות ועברו השפחות וילדיהן ראשונה ואחריהן לאה וילדיה ואחריהן יוסף ורחל ושם אחרון החביב לו יותר כדי שאם ינצל דבר שינצל היותר חביב לו. והוא עבר לפניהם ונכנע בכל עוז אל עשו עד שכבר השתחוה ארצה שבע פעמים עד גשתו עד אחיו וכראו' עשו זה ההכנע הנפלא עם מה שראה מהפלגת המנח' רץ לקראתו וחבקהו ונפל על צואריו ונשק אותו ויבכו כמשפט האחים שעמדו זמן רב שלא ראה איש את אחיו. וישא עיניו עשו וירא הנשים ואת הילדים ויאמר מי אלה שהם לך והשיב יעקב שהם הילדים אשר חנן יי' את עבדך ותגשן לעשו השפחות הנה וילדיהן ותשתחון וכן עשו לאה ויליד' ורחל ויוסף כי כן צוה להם יעקב או עשו זה מפני ראותם שהשתחוה יעקב לעשו. ויאמר עשו ליעקב מי הוא שתשוה לך אהבתו ותקות גמולו כל המחנה הזה אשר פגתי כי באמת להפלגת המנחה לא יוכל איש לשלם לך גמול הראוי עליה כראוי לך והשיב יעקב שלא שלח זאת המנחה לתקו' גמול כ"א למצא חן בעיני עשו ודי לו בזה הגמול והשיב עשו שיש לו רב ושלא יקח דבר ויפצר בו ויקח ויאמר עשו אל יעקב נסע ונלך יחד ואלך לרגליך ויאמר אליו אדני יודע כי הילדים רכים כי כבר היה בהם מי שאין לו זולת שש שנים והיו בהם רבים פחותים משתים עשרה שנה וג"כ הצאן והבקר המניקות עולליהם הם אצלי ועלי הנהגתם ואם לסבת המהירות ידפקום ברצותי למהר רגלי מפני המוסר כשתלך עמי ומתו כל הצאן והנה תלה הקללה בצאן לפי שהוא הפחות מכל המינים שזכר שהיו בסכנה אם ימהר תנועתו. ובהיות הענין כן חליתי פני אדני שיעבור לפני עבדו וישוב למקומו ואני אלך בנחת לרגל המלאכה אשר לפני ולרגל הילדים עד אשר אבא אל אדני שעירה. ויאמר עשו אחר שלא תתרצה שאלך עמך הנה אניח עמך מן העם אשר אתי לשמרך בדרך ולא רצה יעקב בזה כי בטח בשם יתע' ולא שם בשר זרועו עם שכבר היה לו לירא מהנשארים מהעם אשר אתו שלא יזיקוהו. ויעקב נסע סכותה והלך למקום שקראו שמו סכות ויבן לו שם בית ולמקנהו עשה סכו' על כן קרא שם המקום ההו' סכות וכן היה נקרא בעת מתן תורה ואחרי כן כמו שהוא בספר שפטים ויודע בהם אנשי סכות ואמנם נזכר להוסיף האמנה בזה הספור. זה ביאור דברי הפרשה. והנה התועלות המגיעות מזה הספור הם רבים:
@48 **ויבא יעקב שלם וגו' עד סוף הפרשה:**
@48 **באור הפרשה:**
@48 **ספר** שכבר בא יעקב בשלום מעת הפרדו מלבן עד אשר היה בעיר שכם והנה לפני עיר שכם והנה קנה שם חלקת השדה אשר נטה אהלו מיד בני חמור שהיה נשיא הארץ. והיה אבי שכם שענה דינה בת יעקב כמו שספר אחר זה. ולזה תואר אותו בשהוא אבי שכם והנה קנה אותם בדמים מעטים כי לא הלך בגדולות לבקש מקום רחב לנטות שם אהלו אבל הספיק לו ההכרחי. והנה הציב לו שם מזבח ולא בנה מזבח במקום אחר קודם לזה לפי שעד עתה לא נכנס בארץ כנען אשר היא נבחרת ולזה בנה לו שם המזבח כדי שתגיע לו שם הנבואה וכבר קרא לו אל אלהי ישראל בנבואה שם ולזה בנה שם המזבח כדי שתדבק בו ההשפעה האלהית. והנה יצאה דינה בת לאה לראות בבנות הארץ ולפי שעשתה שלא כהוגן השיגה זה המקרה הרע והוא שכבר ראה אותה שכם בן חמור החוי נשיא הארץ ולקחה אותה וישכב אותה ונקשרה אהבתו בה. וידבר על לבה למשוך לבבה להשמע אליו ואמר שכם אל חמור אביו מרוב חשקו בה שיקח לו הילדה הזאת לאש' והנה יעקב שמע זה הפועל המגונה והחריש עד בוא בניו כי היו עם מקנהו בשדה וכאשר יצא חמור אבי שכם אל יעקב לדבר אתו שיתן דינה בתו לשכם בנו לאשה כבר באו בני יעקב מן השדה ויתעצבו מאד כאשר שמעו זה העניין ויחר להם מאד כי נבלה עשה בישראל לשכב את בת יעקב איש אשר לו ערלה כי הם לא ירצו להתחתן עמו בשום פנים ועוד שזה הפועל לא היה ראוי להעשות אע"פ שיהיו לעם אחד ויאותו להתחתן עמהם כי בני נח נצטוו על העריות כמו שקדם. ואמר להם חמור שיתנו את דינה לשכם לאשה ויתחתנו עמהם בדרך שיהיו לעם אחד וישבו עמהם ויסחרו הארץ ויאחזו בה. ולפי שראה שכם שלא היה בזה המאמר מהפיוס מה שיצטרך השלים המאמר לפייס אותם ואמר להם שירבו עליו מאד מוהר ומתן ויתן כאשר יאמרו לו ויתנו לו את דינה לאשה. ויענו בני יעקב את חמור ואת שכם אביו במרמה להנקם מהנבלה הזאת ויאמרו לא נוכל את אחותינו לאיש אשר לו ערלה כי הערלה חרפה היא לנו. ולזה אם תסכימו להמול לכם כל זכר נאות לכם לתת את אחותנו לשכם. ואם לא תסכימו בזה ולקחנו את בתנו והלכנו. והנה כוונו בזה לאחד משלשה דברים וזה שאולי יקשה להם להמול לקושי זה הפועל במוחלט וכ"ש בגדולים ויהיה זה סבה אל שיהיה להם התנצלות כשלא ייתנו אחותם לשכם כי הוא היה בן נשיא הארץ ולא יוכלו להמנע מעשות חפצו אם לא תהיה שם טענה מספקת ואם היה שיסכימו להמול הנה אולי יוכלו להנקם מהם בעת היותם כואבים. ויהרגו כל זכר ואם לא ישלם להם זה הנה עכ"פ יועיל להם זה שלא תהיה אחותם לאיש אשר לו ערלה וזאת היתה החכמה והמרמה אשר היתה בזה המענה. וייטבו דבריהם בעיני חמור ובעיני בנו והשתדלו עם אנשי עיר' שימולו כל זכר ושמעו להם וימולו כל זכר כל יוצאי שער עירם ויתכן שמלו אותם בני יעקב. ויהי ביום השלישי בהיותם כואבים לקחו שמעון ולוי איש חרבו ובאו על העיר בטח והרגו כל זכר ויתכן שהם אמרו שכבר באו לבקר האנשים הנמולים להשתדל ברפואת מכתם וסבבו שלא ישאר בחדר ההוא אחד מהנשים והטף בדרך שלא יודע הדבר והיו הורגים אותם בחרב אשר לקחו וסוגרים הדלת אחריהם וצוו הטף והנשים שלא יכנסו שם כדי שינוחו ממחץ מכתם עד שכבר הרגו כל זכר בעיר קודם שהרגישו בזה הפועל והרגו את שכם וחמור אביו ולקחו דינה מביתם ויצאו וכשנשלם להם הריגת כל זכר בעיר נתקבצו בני יעקב כלם לשלל שלל ולבוז בז להנקם מהם על אשר טמאו אחותם ולקחו צאנם ובקרם וחמוריהם ואשר בעיר ואשר בשדה לקחו ואת כל חילם וטפם ונשיהם שבו ויבוזו ואת כל המטלטלים אשר בבית והנה כעס יעקב על שמעון ולוי ואמר להם עכרתם אותי לשים שנאה ביני ובין יושבי הארץ והם הכנעני והפריזי שהם אומות גדולות ואני במתי מעט ונאספו עלי והכוני ונשמרתי אני וביתי ויאמרו לו האם ראוי שיעשה שכם אחותנו כזונה שלא יהיה בן נח נהרג עליה והנה לא היה אפשר להרוג שכם אם לא בזה האופן כי אם יהרגוהו לבדו ינקמו נקמתו אביו וכל יושבי עירו וידם גם כן היה במעל הזה כי היה בידם למחות לו לעשות זה הפועל המגונה או מפני שלא השתדלו שיהיה נהרג עלי' כמשפט ולזה הרגו כולם. ויאמר אלהים אל יעקב קום עלה ביתאל ושב שם ועשה שם מזבח לאל הנראה אליך בברחך מפני עשו אחיך כי שם תגיע לך הנבואה גם כן כמו שמגעת לך בזה המקום והנה צוהו שיסור משם ולא יסמוך על הנס כי אולי יזיקהו יושבי הארץ וידרשו דמי אנשי שכם מידם והנה השגיח יעקב ועיין בתיקון ענייני ביתו באופן שתדבק בהם ההשגחה האלהית וראה שהיו בביתו מאלילי עיר שכם וצוה שיסירו אלהי הנכר אשר בתוכם ויטהרו ויחליפו שמלותם כי המקום שהולכים שם הוא קדוש. ולזה ראוי שיהיו נקיים מכל טומאה ועוד שהוא יעשה שם מזבח לאל אשר פדה אותו מכח צרה. ולזה ראוי שיקדשו עצמם באופן שתדבק בם השגחתו והנה נתנו ליעקב כל אלהי הנכר אשר בידם והנזמים אשר באזניהם שהיו מוכנים לעשות מהם אלילים או אולי היו מתכשיטי ע"ז והנה קבר אותם יעקב תחת האלה אשר עם שכם שלא יהנו מע"ז כלל. ויסעו והנה עזרם ה' יתע' שהביא חתת ופחד על הערים אשר סביבותיהם ולא רדפו אחרי בני יעקב. ויבא יעקב וכל העם אשר אתו ללוז אשר בארץ כנען היא ביתאל כי כן קרא שמו יעקב כמו שקדם. ויקרא למקום שבנה המזבח אל ביתאל ר"ל שהשם יתע' שם כי שם נגלו אליו האלהים בברחו מפני אחיו. ותמת דבורה מינקת רבקה ותקבר מתחת לבית אל תחת האלון ויקרא שמו אלון בכות כי שם בכו בכי גדול על דבורה. וירא אלהים אל יעקב עוד בביתאל פעם שנית וזאת הנבואה השנית היתה בבואו מפדם ארם כי הראשונה היתה בלכתו שם והנה עדיין היה יעקב בא מפדם ארם כי לא הגיע אל אביו עדיין ויברך אותו השם יתעלה ויאמר לו אלהים שמך יעקב לא יקרא עוד שמך יעקב כי אם ישראל יהיה שמך ויקרא שמו ישראל ויאמר לו האלהים אני אל שדי שהנהגתי מספקת להשפיע המציאות ואני מייעד אותך שעוד יצאו' ממך גוי וקהל גוים ומלכי' ממך יצאו. גוי וקהל גוים יצאו מחלציך והנה אמר זה על בנימן שיצאו ממנו מלכים ועוד אני מיעד אותך שהארץ אשר נתתי לאברהם וליצחק הנני נותנ' לך ולזרעך אחריך אתן את הארץ כשיהיו באופן שיהיו ראויים לירש אותה והנה לא הגיעה עוד נבואה ליעקב במקום ההוא אשר דבר אתו השם יתעלה ואמנם אמר זה כי יעקב היה מכין עצמו במקום ההוא אל שתגיע לו שם נבואה ולא עלה בידו. ואולי היה לו מונע אם מצד טרדת המחשבות אם מצד אחר ואמנם זכר שכבר נפסק שם הנבואה ליעקב לפי שהוא יזכר כי יעקב נסע מביתאל והנה לא היה מסכים יעקב לצאת מהמקום ההוא הנבחר לולי הפסק נבואתו במקום ההוא. והנה הציב יעקב מצבה במקום אשר דבר אתו השם יתע' מצבת אבן ונסך עליה נסכים ויצק עליה שמן לעבוד שם השם יתעלה ולהכין עצמו שתגיע לו שם הנבואה והנה קרא יעקב שם המקום אשר דבר אתו שם אלהים ביתאל. והנה קיים בכאן יעקב מה שנדר שהאבן אשר שם מצבה יהיה לו בית אלהים כי שם עבד ה' יתע' ואין ספק שכבר קיים גם כן מה שנדר לתת מעשר לכבוד השם מכל אשר יתן לו. והנה נתן זה למי שהיה ראוי בדור ההוא והנה כאשר ראה יעקב הפסק הנבואה ממנו במקום ההוא נסע מביתאל ללכת ליצחק אביו והנה היה קרוב מאפרת כשילדה רחל ותקש בלדתה ותלד בן. ויהי בצאת נפשה כי מתה ותרא שמו בן אוני ואביו קרא לו בנימין. ותמת רחל ותקבר בדרך אפרת היא בית לחם ואולי לא רצה יעקב להכנס לאפרת לקברה כי ירא מאנשי הארץ על דבר שכם ולא יכול גם כן לשאת אותה למערת המכפלה כי היה רב המרחק וישיגה עפור נפלא קודם הגיעם שם והנה הציב יעקב מצבה גדולה על גברה לכבודה והנה היתה שם המצבה ההיא בעת נתינת התורה וגם בימי שאול בן קיש היתה שם כאמרו בלכתך היום מעמדי ומצאת שני אנשים עם קבורת רחל בגבול בנימן בצלצח וגם היום היא שם לפי מה שספרו לנו רבים. ויסע ישראל משם ויטו הלו רחוק ממגדל עדר כי לא רצה להכנס לעיר ליראתו מאנשי הארץ על דבר שכם. ויהי בשכון ישראל בארץ ההיא הלך ראובן ושכב עם פילגש אביו וכבר שמע זה ישראל ובעבור זה נתן הבכורה שלו לאחד מבניו הנשארים ולפי שכבר נשלמו תולדות יעקב מנה אותם וספר שכבר היו בני יעקב שנים עשר ואמר שכבר נולדו לו בפדן ארם כי כלם נולדו שם לבד בנימן. ויבא יעקב אל יצחק אביו ממרא קרית הארבע הוא חברון אשר גר שם אברהם ויצחק. ויהיו ימי יצחק מאה ושמונים שנה ויגוע יצחק וימת ונאסף הכבוד אל עמיו ר"ל שכבר הגיע לחיים הנצחיים כמו שביארנו בעניין מיתת אברהם. והיה זקן ושבע ימים ויקברו אותו יעקב ועשו בניו והנה מנה תולדות עשו לכבוד יצחק ויעקב ולהודיע גודל מעלת האבות אצל אנשי הארץ ההיא עד שהיו בני עשו נשיאים וגדולים בארץ אשר גרו בה ונתחתן גם כן עשו עם גדולי הארץ עם שבזה תועלת להודיע יחסי בני עשו כי כבר נצטוו ישראל על בני עשו. עדה בת אילון. היא בשמת בת אילון הכתוב באלה תולדות יצחק אבל היו לה שני שמות. אהליבמה בת ענה היא יהודית בת בארי החתי הכתובה בתולדות יצחק אבל היו לה שני שמות וגם לאביה והנה מצאנו שהיה לצבעון בן והיה שמו ענה והוא היה אבי אהליבמה לפי מה שיראה החכם א"ע ואין זה נכון שאלו היה כן היה אומר אהליבמה בת ענה בן צבעון והוא אמר בת ענה בת צבעון. ועוד כי כבר זכר בני שעיר החורי וזכר אחר כן בסדר ההוא הבנים שהוליד כל אחד מהם ולזה תהיה אהליבמה בת עה אחי צבעון. והנכון בעיני שהיא היתה בת ענה אחי צבעון ואמנם גדלה ענה בן צבעון ונקראת בעבור זה בת צבעון כמו שנקראו בני מיכל בת שאול הבנים שגדלה אותם ולזה תמצא שזכר בבני ענה דישון ואהליבמה בת ענה ואלו היתה אהליבמה בתו לא היה צריך לומר בת ענה ואולם אמר בת ענה כי היא באמת בת ענה הנזכר ראשון וזה מבואר מאד. בשמת בת ישמעאל היא מחלת בת ישמעאל אבל היו לה שני שמות. קרח מצאנוהו בבני עשו ומצאנוהו באלופים מתיחס לאלופי בני אליפז במקום אחד ובמקום אחר מיוחם לאלופי בני אהליבמה. ויתכן שקרח היה בן אהליבמה וגדל אותו אליפז ולזה נתיחס עם אלופי בני אליפז ובלי ספק אם היה ממזר לא היה מסופק בן מי היה אצל התורה כי השם יתעלה יודע כל הנסתרות ואמנם רז"ל אמרו זה על צד הדרש לגלגל חיוב ע"י חייב כמנהגם ואולם אמרנו שקרח היה בן אהליבמה לפי שהוא נזכר עם בניה בתורה ובדברי הימים ולא נזכר עם בני אליפז כלל. תמנע מצאנוה פלגש לאליפז והיה גם כן אחות לוטן בן שעיר החורי ולזה הודיע יחוסה להודיע מעלת האבות שזאת היתה בת נשיא הארץ והסכימה להיות פלגש לאליפז בן עשו. ובדברי הימים מצאנוה נזכרת עם בני אליפז ואולי בא אליפז על אם לוטן וילדה לו תמנע ואח"כ היתה פלגשו. לזה לא נתייחסה לשעיר החורי אבל נזכר שהיא אחות לוטן. בת מטרד בת מי זהב נראה שהיא היתה בת איש ששמו מטרד וגדל אותה איש שהיה שמו מי זהב או היה שם אמה מטרד ושם אם מטרד מי זהב או נתייחסה לאביה ולאמה ויהיה מטרד שם אביה ומי זהב שם אמה. והנה המלכים שזכר מלכו כארץ אדום קודם שימלוך מלך לבני ישראל. ולזה הו' מבואר שכל זה היה קודם מתן תורה כי אז היה מלך לבני ישראל והוא משה רבינו ע"ה כי הוא היה מלך כמו שכתוב ויהי בישורון מלך בהתאסף ראשי עם והנה אלה האלופים שזכר בסוף הפרשה שהיו אלופי עשו למשפחותם למקומותם למושבותם בארץ אחוזתם היו כן אחר שמת הדר שהיה המלך השמיני ולזה כתוב בדברי הימים וימת הדר ויהיו אלופי אדום אלוף תמנע אלוף עלוה וגומ' והם היו מפורסמים בעת נתינת התורה והיו יושבים במקומו' חלוקים וכל אחד מאלו היה נשיא במקומו על המשפחה שהיה ממנה. זה ביאור הספור. ואולם התועלות המגיעות ממנה הם רבים:

@1 **התועלת** הראשון הוא במדות. והוא שראוי למי שיש לו שונא וירצה שתסור שנאתו ממנו שתקרב אליו בכל עוז ויגיד לו ענייניו כי בזה מהתקרבות הלבבות מה שלא יעלם וזה כי האדם לא יודיע פרטי ענייניו כי אם לאוהבו ויעלימ' מהשונא וזה אם כן ממה שייסד בלבו שהוא אוהבו וישבר לבבו ותסור שנאתו ממנו ולזה תמצא ששלח יעקב מלאכים לעשו להודיע לו ענייניו כדי שיתיישב בלבו שהוא אוהבו:
@1 **התועלת** השני הוא במדות. והוא שראוי לאדם שיהיה מפחד תמיד וישפוט הדברים ביותר רע שאפשר כדי שיתבונן לקחת עצה להמלט מהם. הלא תראה כי יעקב כששמע שעשו אחיו הולך לקראתו וארבע מאות איש עמו ירא שיהיה בואו להזיק לו ואע"פ שכבר קדמהו היעוד מהשם יתעלה שישמרהו ויהיה עמו והיה אפשר גם כן שישפוט שהוא בא לכבדו ולשמרו ולזה התחכם לקחת עצה על זה כפי מה שאפשר:
@1 **התועלת** הג' הוא במדות. והוא שאין ראוי לאדם כשיראה שהוא מחוייב שיגיע לו רע מה שיתרשל מלקיחת העצה אי זה רע ישתדל להרחיקו יותר ויבחר ברע היותר מעוט כי אולי יתרשל בזה האדם לחשבו שאין ראוי שיבחר ברע ואין העניין כן כי הוא ראוי שיבחר האדם ברע המועט כדי שינצל מרע שהוא יותר חזק ממנו כי הוא מזה הצד טוב. הלא תראה כי יעקב כאשר פחד שישחית עשו כל מחנהו חלקו לשנים לחקותו כי אולי ישאר האחד. ולזאת הסבה גם כן חצה הילדים על לאה ועל רחל ועל שתי השפחות ושם היותר חביב אחרון כדי שאם ישאר מהם דבר ישאר היותר חביב לו:
@1 **התועלת** הד' הוא במדות. והוא שאין ראוי שימנע האדם מהתפלל לש' יתע' ואפילו בעת הסכנה העצומה כאמרם רז"ל חרב חדה מונח על צוארו של אדם אל ימנע עצמו מן הרחמים. הלא תראה כי יעקב אבינו עם היותו בתכלית הסכנה לפי מחשבתו שעשו אחיו היה שונא אותו שנאת מות היה בא כנגדו בדרך עם ארבע מאות איש התפלל לשם שיצילהו:
@1 **התועלת** הה' הוא בדעות. והוא שאפשר שיעד השם יתע' אדם ביעוד טוב ולא יתקיים כאשר היה היעוד גוזר בעצמות שיהיה בו תנאי כמו העניין בזה הייעוד שייעד השם ליעקב שישמרהו בכל אשר ילך שכמו זה היעוד לא יתכן שיתקיים כי אם במי שהוא באופן מהדבקות בשם יתע' שתדבק בו כמו זאת ההשגחה הנפלאה. ולזה ירא יעקב כי שער בעצמו שאין מעלתו באופן שתדבק בו כמו זאת ההשגחה הנפלא' אבל הוא קטן ושפל בערך אל הטובות אשר השפיע לו השם יתע' מצד דבקות ההשגחה בו:
@1 **התועלת** הו' הוא במדות. והוא שראוי לאדם שיותר משלו לתת לשונאו ויכנע לו בתכלית מה שאפשר עד שישלים עמו אע"פ שהיה שונאו פח' המעלה והוא גדול המעלה כי הוא עושה זה ההכנע בעבור עצמו שימלט משונאו לא בעבור שונאו וראוי לו גם כן שיהיה מה שיתן לו באופן שיהיה שלם ויסדרהו בסדור אשר יראה בו המתן יותר גדול. הלא תראה שיעקב נכנע לעשו בכל זה האופן הנפלא ונתן לו זה המתן הנפלא ורצה עם זה השלמות יעקב בו ר"ל שיהיו הזכרים בכל עדר מה שיספיק לנקבות בשלמות וצוה לתת ריוח בין העדרים כדי שיראה המתן יותר גדול:
@1 **התועלת** הז' הוא במדות. והוא שראוי לאדם שישמור מעבור במקום שיהיה בו סכנה אם לא אחר הנסיון שיתברר לו בו שאין סכנה בעברו במקום ההו' ולזה תמצא כי יעקב להיותו משער בעצמו שאם יראה שיהיו בנחל ההוא מים רבים לא יתכן לעבור בהם יוכל לשוב לאחור מבלי שישיגהו בהם נזק רצה לעבור תחלה זה הנחל קודם שהעביר כל אשר לו כי אם העמיס על עצמו להעבירם קודם שנסה עומק המים ומצא המים באופן לא יוכל לעבור הנה לא יוכל לשוב לאחור עם מה שהיה מעביר מנשיו ובניו:
@1 **התועלת** הח' הוא בדעות. והוא להודיע חוזק השגחת השם יתע' בדברים בו עד שכבר הראה ליעקב בנבואה לישב נפשו ממה שהיה מפחד ממנו שהוא ישדר עם אלהים וישור גם כן עם אנשים ויוכל. ולזאת הסבה בעינה צוה לשנות שמו כמו ששנה שם אברהם ושרה כאשר הבטיחו שיהיה לו בן ממנה כאלו אמר שאם היה ראוי שינוצח יעקב הנה ישראל לא ינוצח כאמרם ז"ל אברם אינו מוליד אבל אברהם מוליד. ולזאת הסבה נכפל זה השנוי ליעקב כשיעד לו השם שיהיה לו ממנו גוי וקהל גוים כאלו אמר שאם אין יעקב מוליד עוד הנה ישראל יוליד ולזאת הסבה אמרו ז"ל ששנוי השם הוא אחד מהדברים שמקרעין גזר דינו של אדם:
@1 **התועלת** הט' הוא בדעות. והוא שאי אפשר לאדם שישג מהות השכל הפועל כמו שחשבו זה קצת הקודמים וזהו מה שאמר לו המלאך למה זה תשאל לשמי כמו שבארנו וכבר ביארנו אמתת זה בראשון ממלחמות יי':
@1 **התועלת** הי' הוא להודיע מעלת יעקב וזה שכבר נתקרבה מדרגתו למדרגת המלאך עד שנדמה לו שיאבק עמו עם שיש במה שנשאר לו מהרושם מזאת הנבואה פרסום לאמתת זאת הנבואה והוא שכבר נמצא שהיה צולע על ירכו כשהקיץ. ולזאת הסבה נצטוינו שלא לאכול גיד הנשה אשר על כף הירך כדי שיתפרסם לנו עניין זאת הנבואה הנפלא' עם שבזה רושם גם כן לאמת' עניין זאת הנבוא' אשר היא פנה מפנות התור' וזה שאם לא יאמין בנבואה תפול התור' בכללה:
@48 **התועלת** הא' הוא במדות. והוא שאין ראוי לאדם שישתמש בשל אחרים בהיות לאל ידו. ולזה תראה שהשתדל יעקב לקנות חלקת שדה אשר נטה שם אהלו.
@48 **התועלת** הב' הוא במדות. והוא שראוי לאדם כשיבא לגור במקום מה שיהיה משאו ומתנו עם הנכבדים שבמקום ההוא כדי שתתקרב דעתם לו ויהיה בזה יותר בטוח מהזקי אנשי העיר. ולזה תמצא שקנה יעקב חלקת השדה מיד נשיאי העיר וכן קנה אברהם שדה עפרון לזאת הסבה כי היה מושל בארץ ההיא:
@48 **התועל** הג' הוא במדות. והוא שראוי לאדם שלא יפזר ממונו יותר מדאי אבל יספיק לו ההכרחי. הלא תראה כי יעקב השלם הספיק לו בנטות אהלו במקום בלתי רחב מאד וכבר יורה על זה שכבר קנהו בדמים מעטים:
@48 **התועלת** הד' הוא במדות. והו' שאין ראוי לאשה שתצא מביתה. הלא תראה מה שקרה מהגנות לדינה בצאתה לראות בבנות הארץ עד שכמעט היה זה סבה להשמיד בכל בית אביה לולי יי' שהיה להם:
@48 **התועלת** הה' הוא במדות. והוא שראוי לאדם שיתנהג במדת הסבל כפי מה שאפשר ולא ימהר להראות כעסו על מה שיעשו האנשים כנגדו אבל ימתין זה אל העת הראוי. הלא תראה שיעקב עם חוזק ההפעלות שהיה ראוי שיהיה מתפעל מזאת מנבלה שעשה שכם החריש יעקב עד בוא בניו כדי שתשלם העצה ביניהם איך יתנהגו בזה ועוד שאם תתחדש מריבה בינו ובין שכם היה יותר טוב שיהיו יחד לקחת עצה איך ינצלו מהם ואם היו בחוץ את מקנהו היה אפשר שיזיקום בקלות הקמים עליהם:
@48 **התועלת** הו' הוא במדות. והוא שאין ראוי לשלם שיוציא דבר מרמה מפיו אפילו לכוין אל מה שראוי שיכוין אליו אבל ראוי שיהיו פיו ולבו שוים ולזאת הסבה לא רצה יעקב לענות לשכם ולחמור אביו מה שהיתה ההסכמה שיענוהו לפי שזה המענה לא היה לפי האמת כי בלי ספק לא יאותו לתת אחותם לשכם ואף על פי שיסכימו להמול כי לא יספיק להם בהסכימם להמול להיות' עמהם לעם אחד כי הם היו עובדים ע"ז ובלי ספק לא יסכימו להיות לעם אחד עם עובדי ע"ז אבל חשבו שבזה ימלטו מנתינת דינה לו לאשה לפי שכבר יקשה להם להמול ויהיה זה סבה אל שיהיה להם התנצלות כאשר לא יסכימו לתת לו אחותם. והנה לזאת הסבה ענו בני יעקב זה המענה לפני אביהם כי לא היה להם עזות מצח לענות בפניו לולי כי לא הסכים לענות כמו זה המענה בפיו ולזה תמצ' שכאשר הסכימו להמול ויוכרחו לתת לו אחותם. והוא מה שברחו ממנו עם מה שימשך להם בזה מההפסד שיתערבו עם עובדי ע"ז ויהיו עמהם לעם אחד ולא יהיה להם אות יוכר בו זרעם עד שיהיה זה סבה שיתערב זרעם בהם וימשכו לאמונתם הנפסדת כל שכן עם התחתנם זה בזה כמו שהתנו הנה להתמלט נפשם מזה ההפסד התעוררו לעשות זה הפועל הנפלא:
@48 **התועלת** השביעי הוא במדות. והוא שאין ראוי לאדם שיחמוד שיהיה לו מה שלזולתו מהקניינים כי זאת מדה פחותה מאד מביאה להפסד רב הקבוצים המדיניים ולזה תראה שספר ששכם וחמור כאשר נתנו עיניהם במקנה יעקב ובקניניו וקוו שיהיו להם וקרה להם הפך זה והוא שכבר היה ליעקב כל מקניהם וקנינם:
@48 **התועלת** השמיני הוא במדות. והוא שאין ראוי לאדם למסור עצמו לסכנות הלא תראה כי יעקב עם מה שהגיע לו מהיעוד מהש' יתע' שישמרהו תמיד פחד פחד נפלא כשעשו בניו זה הפועל חזר ויירא מאנשי הארץ שישמידוהו הוא וביתו:
@48 **התועלת** התשיעי הוא בדעות. והוא שהש' יתע' כשיעזור לדבקים בו ושומר אותם יעשה זה בסבות היותר נאותות ולזה צוה השם יתע' ליעקב שיסור משם פן תדבקנו הרעה מאנשי הארץ וילך לביתאל ויעשה לו שם מזבח לעבוד בו השם יתע' כדי שישלם לו שם הדבקות בשם יתע' ביותר שלם שאפשר עד שתדבק בו ההשגחה האלהית. ולזאת הסבה בעינה צוה המלאך ללוט שימלט ההרה פן תדבקנו הרעה שם ולא הסכים השם יתע' להצילו לבדו במקום שהיה בו כי הוא יבקש תמיד כמה שיעשהו מאלו הענינים שיהיו באמצעות הסבות אשר בהם יותר מעט מהזרות אל הסדור הטבעי וכבר בארנו זה בששי ממלחמות יי':
@48 **התועלת** העשירי הוא במדות. והוא שראוי לאדם כשיירא ממקרים רעים שישוב אל השם יתע' בכל עוז ויסיר מביתו כל דבר מוגנה כי בזה יתקרב להשם יתע' וירחמהו ולזה צוה יעקב לנקות ביתו מכל דבר רע בהיותו ירא מאנשי הארץ שישמידוהו הוא וביתו והנה הסכים יעקב שלא להנות מע"ז לסבה בעינה אשר מנעה התורה ההנאה ממנה:
@48 **התועלת** האחד עשר הוא במדות. והוא שראוי לאדם לגמול חסד עם המתים אשר הגיע לו מהם טוב בחייהם ולזה ספר שכבר קרא יעקב אלון בכות שם האלון אשר נקברה שם דבורה מניקת רבקה כי זה ממה שיורה שכבר בכה שם ולזאת הסבה בעינה הציב יעקב מצבה על קבורת רחל באופן שהציב אותה כדי שישאר זכרה זמן ארוך כי בזה מגמילות חסדים מה שלא יעלם:
@48 **התועלת** השנים עשר הוא במדות. והוא שראוי לאדם שלא יפליג לכעוס על בנו הגדול על פעולותיו המגונות כי אולי יטרידהו ממנו ויפסידהו אבל ראוי לו אז שיקריבהו אליו יותר להדריכו בדרך ישרה. ולזאת הסבה ספר שכבר שמע ישראל זה הפועל המגונה אשר עשה ראובן ולא זכר שכעס עליו. ואולם ביום צוותו את בניו ענשו על זה הפועל המגונה ועשק ממנו הבכורה ונתנה ליוסף. והנה זכר אחר זה הסבה אשר הוכרחו בעבורה אל שיפרדו יעקב ועשו איש מעל אחיו עם היותם אחים לישב יותר בלבנו אמונת החדוש ותאריך בספור תולדות עשו ובספור המלכים אשר מלכו בארץ אדום לכבוד האבות ולהודיע יחוסיהם להפרידם מבני שעיר כי ישראל צוו על בני עשו כמו שביארנו במה שקדם:
